function generarPDF(tipo) {
  var cfg = PDF_BLANK_MAP[tipo];
  if (!cfg) { toast('Formulario no disponible','error'); return; }
  var vistaEl = document.getElementById(cfg.vistaId);
  if (!vistaEl) { toast('Vista no encontrada','error'); return; }

  // Clonar la vista y preparar para impresión
  var clone = vistaEl.cloneNode(true);

  // STAI tiene dos sub-escalas (Estado/Rasgo) en pestañas; la pestaña no activa
  // queda con display:none y se perdería al imprimir. Mostrar ambas con su título.
  if (tipo === 'stai') {
    var staiTabs = clone.querySelector('.stai-tabs');
    if (staiTabs) staiTabs.parentNode.removeChild(staiTabs);
    var staiE = clone.querySelector('#stai-items-e');
    var staiR = clone.querySelector('#stai-items-r');
    if (staiE) staiE.insertAdjacentHTML('beforebegin', '<div class="card-title" style="margin-top:6px;">Ansiedad Estado (E) — cómo se siente en este momento</div>');
    if (staiR) {
      staiR.style.display = 'block';
      staiR.insertAdjacentHTML('beforebegin', '<div class="card-title" style="margin-top:20px;">Ansiedad Rasgo (R) — cómo se siente generalmente</div>');
    }
  }

  // Ocultar botones, resultados y elementos de navegación
  Array.from(clone.querySelectorAll('.back-btn, .btn-row, [id$="-resultado"], .btn-primary, .btn-secondary, button')).forEach(function(el){
    el.style.display = 'none';
  });
  // Mostrar solo el formulario (form div)
  Array.from(clone.querySelectorAll('[id$="-form"]')).forEach(function(el){
    el.style.display = 'block';
  });
  // Resetear estilos del clone
  clone.style.cssText = 'display:block;padding:0;margin:0;background:#fff;';
  clone.className = '';
  // Remover el botón de imprimir que pueda estar en el formulario
  Array.from(clone.querySelectorAll('[onclick*="generarPDF"], [onclick*="window.print"]')).forEach(function(el){
    el.parentNode && el.parentNode.removeChild(el);
  });

  // CSS base del sistema para que los estilos de items, radio buttons, etc funcionen
  var estilosApp = '';
  Array.from(document.styleSheets).forEach(function(ss){
    try {
      Array.from(ss.cssRules||[]).forEach(function(r){ estilosApp += r.cssText + '\n'; });
    } catch(e){}
  });

  var html = '<!DOCTYPE html><html><head><meta charset="utf-8">'+
    '<title>'+cfg.titulo+'</title>'+
    '<style>'+
      estilosApp+
      'body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;margin:20px;padding:0;}'+
      '.vista-header{margin-bottom:12px;}'+
      '.vista-titulo{font-size:14pt;font-weight:700;color:#1a2e16;border-bottom:2px solid #325c28;padding-bottom:6px;}'+
      '.card{background:#fff;border:0.5px solid #ddd;border-radius:6px;padding:14px;margin-bottom:12px;}'+
      '.card-title{font-size:10pt;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#2a6e6e;border-bottom:1px solid #b8ddb0;margin-bottom:10px;padding-bottom:4px;}'+
      '.form-grid, .form-grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:8px;}'+
      '.field label{display:block;font-size:8pt;font-weight:700;color:#3a8f8f;margin-bottom:3px;text-transform:uppercase;letter-spacing:0.3px;}'+
      'input[type="number"],select,input[type="date"],input[type="text"]{width:100%;box-sizing:border-box;border:1px solid #ccc;border-radius:4px;padding:4px 6px;font-size:10pt;}'+
      '.scl-block,.spai-block,.asrs-block,.wurs-block,.mbi-block{margin-bottom:8px;}'+
      '.item-row,.spai-item,.scl-item{display:flex;align-items:flex-start;gap:6px;padding:3px 0;border-bottom:0.3px solid #eee;font-size:9pt;}'+
      '.item-num,.spai-num,.scl-num{min-width:22px;font-weight:700;color:#4a7040;font-size:8pt;padding-top:2px;}'+
      '.item-text,.spai-item-text,.scl-item-text{flex:1;line-height:1.4;}'+
      '.likert-opts,.radio-opts{display:flex;gap:8px;min-width:120px;justify-content:flex-end;}'+
      '.likert-opt,.radio-opt{display:flex;flex-direction:column;align-items:center;font-size:7.5pt;gap:2px;}'+
      'input[type="radio"],input[type="checkbox"]{margin:0;}'+
      '@media print{body{margin:10mm;}@page{size:A4;margin:15mm;}}'+
    '</style></head><body>'+
    '<div style="text-align:center;margin-bottom:14px;">'+
      '<div style="font-size:11pt;font-weight:700;color:#2a6e6e;">CENTRO DE REHABILITACIÓN GONZÁLEZ PALAU - FUNDACIÓN CIATEC</div>'+
      '<div style="font-size:8pt;color:#666;margin-top:2px;">Neuropsicología – Neuro rehabilitación – Psicoterapia</div>'+
      '<div style="font-size:8pt;color:#666;">Av. Laplace 5264 – Villa Belgrano, Córdoba – Tel/whatsapp: 3515513257 – E-mail: secretariafgonzalezp@gmail.com</div>'+
      '<div style="font-size:13pt;font-weight:800;color:#1a2e16;margin-top:8px;">'+cfg.titulo+'</div>'+
      '<div style="margin-top:8px;font-size:9pt;display:flex;gap:30px;justify-content:center;">'+
        '<span>Paciente: ____________________________</span>'+
        '<span>Fecha: ____________</span>'+
        '<span>Edad: ______</span>'+
      '</div>'+
    '</div>'+
    clone.innerHTML+
    '</body></html>';

  var win = window.open('', '_blank', 'width=900,height=700');
  if (!win) { toast('Permitir pop-ups para imprimir','error'); return; }
  win.document.open();
  win.document.write(html);
  win.document.close();
  win.onload = function(){ win.focus(); win.print(); };
}

// Formatea números para tablas de informe (máx. 1 decimal; evita salto de línea en negativos)
function _fmtTabNum(val) {
  if (val === null || val === undefined || val === '—') return '—';
  if (typeof val === 'string' && /[\/%seg·]/.test(val)) return val;
  var n = parseFloat(val);
  if (isNaN(n)) return String(val);
  if (Math.abs(n - Math.round(n)) < 1e-9) return String(Math.round(n));
  return (Math.round(n * 10) / 10).toFixed(1);
}

function _parseResultDatos(raw) {
  if (!raw) return {};
  if (typeof raw === 'string') {
    try { return JSON.parse(raw); } catch (e) { return {}; }
  }
  return raw;
}

function zInterpNormativo(z) {
  if (z === null || z === undefined || isNaN(parseFloat(z))) return '—';
  return zNormMeta(z, false).label;
}

function fmtZInforme(z) {
  if (z === null || z === undefined || isNaN(parseFloat(z))) return null;
  z = parseFloat(z);
  return (z >= 0 ? '+' : '') + z.toFixed(2);
}

