var _npChipActivo = 'todos';

function npBuildVistaTests() {
  if (window._npVistaTests) return window._npVistaTests;
  var m = {};
  Object.keys(TEST_NOMBRE_A_VISTA).forEach(function(tn) {
    var v = TEST_NOMBRE_A_VISTA[tn];
    if (!m[v]) m[v] = [];
    if (m[v].indexOf(tn) < 0) m[v].push(tn);
  });
  m.sdmt = ['SDMT-escrita', 'SDMT-oral'];
  m.bnt = ['BNT-12', 'BNT-60'];
  window._npVistaTests = m;
  return m;
}

function npPacienteTieneTest(npId) {
  if (!PAC_ACTIVO || !PAC_ACTIVO.id) return false;
  var tests = npBuildVistaTests()[npId];
  if (!tests || !tests.length) return false;
  var pacId = String(PAC_ACTIVO.id);
  return RESULTADOS.some(function(r) {
    return String(r.paciente_id) === pacId && tests.indexOf(r.test) >= 0;
  });
}

function npBadgeHtml(npId) {
  if (!PAC_ACTIVO || !PAC_ACTIVO.id) return '';
  if (npPacienteTieneTest(npId)) {
    return '<span class="np-estado-badge guardado" title="Resultado guardado para este paciente">' +
      '<span class="np-estado-ico">✓</span> Guardado</span>';
  }
  return '<span class="np-estado-badge pendiente" title="Pendiente de cargar para este paciente">' +
    '<span class="np-estado-ico">⏳</span> Pendiente</span>';
}

function npActualizarEstados() {
  if (!document.getElementById('np-grid')) return;
  npRender();
}

function npChip(el, dom) {
  document.querySelectorAll('.np-chip').forEach(function(c){ c.classList.remove('active'); });
  el.classList.add('active');
  _npChipActivo = dom;
  npRender();
}
function npRender() {
  var qEl = document.getElementById('np-q');
  var q = qEl ? qEl.value.toLowerCase() : '';
  var r = NP_TESTS.filter(function(t) {
    var dok = _npChipActivo === 'todos' || t.dom === _npChipActivo;
    var tok = !q || (t.n + ' ' + t.d + ' ' + t.t).toLowerCase().includes(q);
    return dok && tok;
  });
  var grid = document.getElementById('np-grid');
  if (!grid) return;
  grid.innerHTML = r.map(function(t) {
    var ico = NP_ICONS[t.dom] || '';
    return '<div class="test-card" onclick="irTest(\'' + t.id + '\')">' +
      '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:3px;">' +
        '<div style="display:flex;align-items:center;gap:7px;min-width:0;">' + ico +
          '<span class="test-nombre" style="margin:0;">' + t.n + '</span>' +
        '</div>' +
        npBadgeHtml(t.id) +
      '</div>' +
      '<div class="test-desc">' + t.d + '</div>' +
      '<span class="test-tag">' + t.t + '</span>' +
      '</div>';
  }).join('') || '<div style="padding:20px;text-align:center;font-size:12px;color:var(--muted);">Sin resultados</div>';
}

