// ══ BDI-II ═══════════════════════════════════════════════════════════════════
var BDI_ITEMS = [
  {n:'Tristeza', ops:['No me siento triste.','Me siento triste gran parte del tiempo.','Me siento triste continuamente.','Me siento tan triste o tan desgraciado/a que no puedo soportarlo.']},
  {n:'Pesimismo', ops:['No estoy desanimado/a sobre mi futuro.','Me siento más desanimado/a sobre mi futuro que antes.','No espero que las cosas mejoren.','Siento que mi futuro es desesperanzador y que las cosas sólo empeorarán.']},
  {n:'Fracaso', ops:['No me siento fracasado/a.','He fracasado más de lo que debería.','Cuando miro atrás, veo muchos fracasos.','Siento que soy un fracaso total como persona.']},
  {n:'Pérdida de placer', ops:['Obtengo tanto placer como siempre de las cosas que disfruto.','No disfruto tanto de las cosas como antes.','Obtengo muy poco placer de las cosas que antes disfrutaba.','No obtengo ningún placer de las cosas que antes disfrutaba.']},
  {n:'Sentimientos de culpa', ops:['No me siento especialmente culpable.','Me siento culpable de muchas cosas que he hecho o debería haber hecho.','Me siento bastante culpable la mayor parte del tiempo.','Me siento culpable constantemente.']},
  {n:'Sentimientos de castigo', ops:['No siento que esté siendo castigado/a.','Siento que puedo ser castigado/a.','Espero ser castigado/a.','Siento que estoy siendo castigado/a.']},
  {n:'Insatisfacción con uno mismo', ops:['Siento lo mismo sobre mí mismo/a que antes.','He perdido confianza en mí mismo/a.','Estoy decepcionado/a conmigo mismo/a.','No me gusto.']},
  {n:'Autocrítica', ops:['No me critico más de lo habitual.','Me critico más de lo habitual.','Me critico por todos mis defectos.','Me culpo de todo lo malo que me sucede.']},
  {n:'Pensamientos suicidas', ops:['No tengo ningún pensamiento de suicidio.','Tengo pensamientos de suicidio, pero no los llevaría a cabo.','Me gustaría suicidarme.','Me suicidaría si tuviera la oportunidad.']},
  {n:'Llanto', ops:['No lloro más de lo habitual.','Lloro más de lo habitual.','Lloro por cualquier cosa.','Siento ganas de llorar continuamente, pero no puedo.']},
  {n:'Agitación', ops:['No me siento más inquieto/a o tenso/a que de costumbre.','Me siento más inquieto/a o tenso/a que de costumbre.','Estoy tan inquieto/a o agitado/a que me es difícil quedarme quieto/a.','Estoy tan inquieto/a o agitado/a que tengo que estar continuamente en movimiento o haciendo algo.']},
  {n:'Pérdida de interés', ops:['No he perdido el interés por otras personas o actividades.','Estoy menos interesado/a que antes en otras personas o cosas.','He perdido la mayor parte de mi interés por los demás o por las cosas.','Me es difícil interesarme en algo.']},
  {n:'Indecisión', ops:['Tomo decisiones más o menos como siempre.','Me resulta más difícil que de costumbre tomar decisiones.','Tengo mucha más dificultad en tomar decisiones que de costumbre.','Tengo problemas para tomar cualquier decisión.']},
  {n:'Inutilidad', ops:['No me siento inútil.','No me considero tan valioso y útil como solía ser.','Me siento menos valioso en comparación con otras personas.','Siento que no valgo nada.']},
  {n:'Pérdida de energía', ops:['Tengo tanta energía como siempre.','Tengo menos energía que antes.','No tengo suficiente energía para hacer demasiado.','No tengo energía suficiente para hacer nada.']},
  {n:'Cambios en el sueño', ops:['No he experimentado ningún cambio en mi patrón de sueño.','Duermo algo más/menos que de costumbre.','Duermo bastante más/menos que de costumbre.','Duermo la mayor parte del día o me despierto 1-2 horas antes de lo habitual.']},
  {n:'Irritabilidad', ops:['No estoy más irritable que de costumbre.','Estoy más irritable que de costumbre.','Estoy bastante más irritable que de costumbre.','Estoy irritable continuamente.']},
  {n:'Cambios en el apetito', ops:['No he experimentado ningún cambio en mi apetito.','Mi apetito es algo menor/mayor que de costumbre.','Mi apetito es bastante menor/mayor que de costumbre.','No tengo apetito o sólo tengo ganas de comer constantemente.']},
  {n:'Dificultad de concentración', ops:['Puedo concentrarme tan bien como siempre.','No puedo concentrarme tan bien como habitualmente.','Me es difícil mantener la mente en algo por mucho tiempo.','No puedo concentrarme en nada.']},
  {n:'Cansancio', ops:['No estoy más cansado/a de lo habitual.','Me canso más fácilmente que de costumbre.','Estoy demasiado cansado/a para hacer muchas cosas que solía hacer.','Estoy demasiado cansado/a para hacer la mayoría de cosas que solía hacer.']},
  {n:'Pérdida de interés en el sexo', ops:['No he notado ningún cambio reciente en mi interés por el sexo.','Estoy menos interesado/a por el sexo que antes.','Estoy mucho menos interesado/a por el sexo.','He perdido completamente el interés por el sexo.']}
];

