function setModo(testId, modo) {
  var btnAuto = document.getElementById('modo-auto-'+testId);
  var btnMan  = document.getElementById('modo-man-'+testId);
  var autoArea = document.getElementById('auto-area-'+testId);
  var manArea  = document.getElementById('man-area-'+testId);
  if (!btnAuto || !btnMan) return;
  if (modo === 'manual') {
    btnAuto.classList.remove('active'); btnMan.classList.add('active');
    if (autoArea) autoArea.style.display = 'none';
    if (manArea)  manArea.style.display  = 'block';
  } else {
    btnMan.classList.remove('active'); btnAuto.classList.add('active');
    if (autoArea) autoArea.style.display = 'block';
    if (manArea)  manArea.style.display  = 'none';
  }
  if (testId === 'fcr') {
    if (typeof fcrToggleExactitudGrid === 'function') fcrToggleExactitudGrid();
    if (typeof fcrSyncExactitudFields === 'function') fcrSyncExactitudFields();
    if (typeof fcrActualizar === 'function') fcrActualizar();
  }
}

function calcularManual(testId) {
  var campos = MANUAL_CAMPOS[testId];
  if (!campos) return;
  // Validar que todos los campos tengan valor
  for (var i = 0; i < campos.length; i++) {
    var v = document.getElementById(campos[i].id);
    if (!v || v.value === '') { toast('Completá todos los campos','error'); return; }
  }
  // Inyectar valores en los campos del formulario automático según test
  if (testId === 'bdi') {
    var total = parseInt(document.getElementById('man-bdi-total').value);
    // Distribuir en ítems: item 0 = total, resto en 0
    for (var j = 0; j < 21; j++) {
      var opts = document.querySelectorAll('[name="bdi_'+j+'"]');
      opts.forEach(function(o){ o.checked = false; });
      var opt0 = document.querySelector('[name="bdi_'+j+'"][value="0"]');
      if (opt0) opt0.checked = true;
    }
    // Sobreescribir cálculo directo
    _calcularBDIManual(total);
    return;
  }
  if (testId === 'stai') {
    var ptsE = parseInt(document.getElementById('man-stai-e').value);
    var ptsR = parseInt(document.getElementById('man-stai-r').value);
    var sexo = document.getElementById('stai-sexo').value;
    if (!sexo) { toast('Seleccioná el sexo','error'); return; }
    _calcularSTAIManual(ptsE, ptsR, sexo);
    return;
  }
  if (testId === 'phq') { _calcularPHQManual(parseInt(document.getElementById('man-phq-total').value)); return; }
  if (testId === 'gad') { _calcularGADManual(parseInt(document.getElementById('man-gad-total').value)); return; }
  if (testId === 'birleson') { _calcularBirlesonManual(parseInt(document.getElementById('man-birleson-total').value)); return; }
  if (testId === 'aaa') { _calcularAAAManual(parseInt(document.getElementById('man-aaa-total').value)); return; }
  if (testId === 'spaib') { _calcularSPAIBManual(parseInt(document.getElementById('man-spaib-total').value)); return; }
  if (testId === 'asrs') {
    var secA = parseInt(document.getElementById('man-asrs-a').value);
    var sI   = parseInt(document.getElementById('man-asrs-i').value);
    var sH   = parseInt(document.getElementById('man-asrs-h').value);
    var sT   = parseInt(document.getElementById('man-asrs-t').value);
    var gr   = document.getElementById('asrs-grupo').value;
    if (!gr) { toast('Seleccioná el grupo etario','error'); return; }
    _calcularASRSManual(secA, sI, sH, sT, gr);
    return;
  }
  if (testId === 'wurs') { _calcularWURSManual(parseInt(document.getElementById('man-wurs-total').value)); return; }
  if (testId === 'mbi') {
    var ce = parseInt(document.getElementById('man-mbi-ce').value);
    var dp = parseInt(document.getElementById('man-mbi-dp').value);
    var rp = parseInt(document.getElementById('man-mbi-rp').value);
    _calcularMBIManual(ce, dp, rp);
    return;
  }
  if (testId === 'csi') {
    var vals = {};
    ['REP','AUC','EEM','PSD','APS','REC','EVP','RES'].forEach(function(k,i){
      vals[k] = parseInt(document.getElementById('man-csi-'+k.toLowerCase()).value)||0;
    });
    _calcularCSIManual(vals);
    return;
  }
}

// ── Funciones de cálculo manual por test ──────────────────────────────────

function _calcularBDIManual(total) {
  var cat, rango, badge;
  if (total <= 13)      { cat='Mínima';   rango='0–13';  badge='bg-minima';   }
  else if (total <= 19) { cat='Leve';     rango='14–19'; badge='bg-leve';     }
  else if (total <= 28) { cat='Moderada'; rango='20–28'; badge='bg-moderada'; }
  else                  { cat='Grave';    rango='29–63'; badge='bg-grave';    }
  document.getElementById('bdi-pts').textContent = total;
  document.getElementById('bdi-cat').textContent = 'Depresión ' + cat;
  document.getElementById('bdi-rango').textContent = 'Rango: ' + rango + ' puntos';
  document.getElementById('bdi-badge').className = 'badge-grande ' + badge;
  document.getElementById('bdi-badge').textContent = 'Depresión ' + cat;
  var interp = '';
  if (total <= 13) interp = '<p>Puntaje ('+total+') en rango de <strong>depresión mínima</strong>. Sin indicadores clínicamente significativos.</p>';
  else if (total <= 19) interp = '<p>Puntaje ('+total+'): <strong>depresión leve</strong>. Se recomienda monitorear evolución.</p>';
  else if (total <= 28) interp = '<p>Puntaje ('+total+'): <strong>depresión moderada</strong>. Impacto en funcionamiento cotidiano. Se recomienda intervención.</p>';
  else interp = '<p>Puntaje ('+total+'): <strong>depresión grave</strong>. Requiere atención clínica inmediata.</p>';
  interp += '<p><em>Carga manual. Integrar con evaluación clínica completa.</em></p>';
  document.getElementById('bdi-interp').innerHTML = interp;
  window._bdiTotal = total;
  document.getElementById('bdi-form').style.display = 'none';
  document.getElementById('bdi-resultado').style.display = 'block';
}

function _calcularSTAIManual(ptsE, ptsR, sexo) {
  var clfE = clasificarSTAI(ptsE, 'e', sexo);
  var clfR = clasificarSTAI(ptsR, 'r', sexo);
  var sexoNom = sexo === 'v' ? 'varones' : 'mujeres';
  document.getElementById('stai-pts-e').textContent = ptsE;
  document.getElementById('stai-pts-r').textContent = ptsR;
  document.getElementById('stai-badge-e').textContent = 'Estado: ' + clfE.cat;
  document.getElementById('stai-badge-e').className = 'badge-grande ' + clfE.badge;
  document.getElementById('stai-badge-r').textContent = 'Rasgo: ' + clfR.cat;
  document.getElementById('stai-badge-r').className = 'badge-grande ' + clfR.badge;
  document.getElementById('stai-percentiles').innerHTML =
    '<div class="detalle-item"><div class="detalle-num">'+ptsE+'</div><div class="detalle-lbl">PD Estado</div></div>'+
    '<div class="detalle-item"><div class="detalle-num">'+clfE.perc+'</div><div class="detalle-lbl">Percentil Estado</div></div>'+
    '<div class="detalle-item"><div class="detalle-num">'+ptsR+'</div><div class="detalle-lbl">PD Rasgo</div></div>'+
    '<div class="detalle-item"><div class="detalle-num">'+clfR.perc+'</div><div class="detalle-lbl">Percentil Rasgo</div></div>'+
    '<div class="detalle-item"><div class="detalle-num">'+sexoNom+'</div><div class="detalle-lbl">Baremo</div></div>';
  document.getElementById('stai-interp').innerHTML = '<p>Estado: '+ptsE+' — '+clfE.cat+' (Pc '+clfE.perc+'). Rasgo: '+ptsR+' — '+clfR.cat+' (Pc '+clfR.perc+'). <em>Carga manual.</em></p>';
  window._staiE = ptsE; window._staiR = ptsR;
  document.getElementById('stai-form').style.display = 'none';
  document.getElementById('stai-resultado').style.display = 'block';
}

