function _calcularASRSManual(secA, sI, sH, sT, grupo) {
  var positivo = secA >= 4;
  var bar = ASRS_BAR[grupo];
  var pcI = asrsBuscarPc(sI, bar.I), pcH = asrsBuscarPc(sH, bar.H), pcT = asrsBuscarPc(sT, bar.T);
  var zI = parseFloat(((sI-bar.I.M)/bar.I.DS).toFixed(2));
  var zH = parseFloat(((sH-bar.H.M)/bar.H.DS).toFixed(2));
  var zT = parseFloat(((sT-bar.T.M)/bar.T.DS).toFixed(2));
  function pcLbl(pc){return pc>=90?'Muy elevado':pc>=75?'Elevado':pc>=40?'Promedio':'Bajo';}
  document.getElementById('asrs-detalle').innerHTML =
    '<div class="detalle-item"><div class="detalle-num">'+(positivo?'✓ Positivo':'✗ Negativo')+'</div><div class="detalle-lbl">Sección A ('+secA+'/6)</div></div>'+
    '<div class="detalle-item"><div class="detalle-num">Pc '+pcI+'</div><div class="detalle-lbl">ASRS-I ('+sI+')</div></div>'+
    '<div class="detalle-item"><div class="detalle-num">Pc '+pcH+'</div><div class="detalle-lbl">ASRS-H ('+sH+')</div></div>'+
    '<div class="detalle-item"><div class="detalle-num">Pc '+pcT+'</div><div class="detalle-lbl">ASRS-T ('+sT+')</div></div>';
  document.getElementById('asrs-interp').innerHTML =
    '<p>Sección A: '+secA+'/6 — '+(positivo?'Screening positivo (≥4)':'Screening negativo')+'. Inatención: '+sI+' (Z='+zI+', Pc'+pcI+'). Hiperactividad: '+sH+' (Z='+zH+', Pc'+pcH+'). Total: '+sT+' (Z='+zT+', Pc'+pcT+'). <em>Carga manual.</em></p>';
  window._asrsData = { secA:secA, sI:sI, sH:sH, sT:sT, pcI:pcI, pcH:pcH, pcT:pcT, zI:zI, zH:zH, zT:zT, grupo:grupo };
  document.getElementById('asrs-form').style.display = 'none';
  document.getElementById('asrs-resultado').style.display = 'block';
}

function _calcularWURSManual(total) {
  var M=23.5, DS=13.16;
  var z = parseFloat(((total-M)/DS).toFixed(2));
  var pc = Math.max(1,Math.min(99,Math.round(50+28.57*z)));
  var cat = total >= 46 ? 'Compatible con TDAH retrospectivo (≥46)' : 'Sin indicadores retrospectivos de TDAH';
  document.getElementById('wurs-detalle').innerHTML =
    '<div class="detalle-item"><div class="detalle-num">'+total+'</div><div class="detalle-lbl">Puntaje total</div></div>'+
    '<div class="detalle-item"><div class="detalle-num">'+(z>=0?'+':'')+z+'</div><div class="detalle-lbl">Z</div></div>'+
    '<div class="detalle-item"><div class="detalle-num">Pc '+pc+'</div><div class="detalle-lbl">Percentil</div></div>';
  document.getElementById('wurs-interp').innerHTML = '<p>'+cat+'. Puntaje: '+total+'/100 (Z='+z+', Pc'+pc+'). <em>Carga manual.</em></p>';
  window._wursTotal = total; window._wursZ = z; window._wursPc = pc;
  document.getElementById('wurs-form').style.display = 'none';
  document.getElementById('wurs-resultado').style.display = 'block';
}

function _calcularMBIManual(ce, dp, rp) {
  function catCE(v){return v>=27?'Alto':v>=17?'Moderado':'Bajo';}
  function catDP(v){return v>=10?'Alto':v>=7?'Moderado':'Bajo';}
  function catRP(v){return v<=33?'Bajo':v<=39?'Moderado':'Alto';}
  var cats = { CE:catCE(ce), DP:catDP(dp), RP:catRP(rp) };
  var burnout = cats.CE==='Alto'||cats.DP==='Alto'||cats.RP==='Bajo';
  document.getElementById('mbi-detalle').innerHTML =
    '<div class="detalle-item"><div class="detalle-num">'+ce+'</div><div class="detalle-lbl">CE ('+cats.CE+')</div></div>'+
    '<div class="detalle-item"><div class="detalle-num">'+dp+'</div><div class="detalle-lbl">DP ('+cats.DP+')</div></div>'+
    '<div class="detalle-item"><div class="detalle-num">'+rp+'</div><div class="detalle-lbl">RP ('+cats.RP+')</div></div>';
  document.getElementById('mbi-interp').innerHTML =
    '<p>CE: '+ce+'/54 ('+cats.CE+') · DP: '+dp+'/30 ('+cats.DP+') · RP: '+rp+'/48 ('+cats.RP+'). '+(burnout?'<strong>Indicadores de burnout presentes.</strong>':'Sin indicadores significativos de burnout.')+' <em>Carga manual.</em></p>';
  window._mbiData = { ce:ce, dp:dp, rp:rp, cats:cats };
  document.getElementById('mbi-form').style.display = 'none';
  document.getElementById('mbi-resultado').style.display = 'block';
}

function _calcularCSIManual(vals) {
  // Usar la misma lógica que calcularCSI pero con valores directos
  var CSI_BAREMOS_MAN = {
    REP:{M:13.6,DS:5.2},AUC:{M:7.9,DS:5.3},EEM:{M:11.9,DS:5.6},
    PSD:{M:10.5,DS:5.4},APS:{M:11.4,DS:5.7},REC:{M:12.3,DS:5.0},
    EVP:{M:10.8,DS:4.9},RES:{M:7.2,DS:4.8}
  };
  var LABELS = {REP:'Resolución de Problemas',AUC:'Autocrítica',EEM:'Expresión Emocional',
    PSD:'Pensamiento Desiderativo',APS:'Apoyo Social',REC:'Reestructuración Cognitiva',
    EVP:'Evitación de Problemas',RES:'Retirada Social'};
  var detalleHtml = '', interpHtml = '<ul>';
  Object.keys(vals).forEach(function(k){
    var v=vals[k], b=CSI_BAREMOS_MAN[k];
    var z=b?parseFloat(((v-b.M)/b.DS).toFixed(2)):null;
    var pc=z!==null?Math.max(1,Math.min(99,Math.round(50+28.57*z))):null;
    detalleHtml += '<div class="detalle-item"><div class="detalle-num">'+(pc!==null?'Pc '+pc:'—')+'</div><div class="detalle-lbl">'+LABELS[k]+' ('+v+')</div></div>';
    interpHtml += '<li>'+LABELS[k]+': '+v+'/16'+(z!==null?' · Z='+(z>=0?'+':'')+z:'')+' (Pc'+(pc||'—')+')</li>';
  });
  interpHtml += '</ul><p><em>Carga manual.</em></p>';
  document.getElementById('csi-detalle').innerHTML = detalleHtml;
  document.getElementById('csi-interp').innerHTML = interpHtml;
  window._csiVals = vals;
  document.getElementById('csi-form').style.display = 'none';
  document.getElementById('csi-resultado').style.display = 'block';
}

function iniciarBDI() {
  var c = document.getElementById('bdi-items-container');
  c.innerHTML = BDI_ITEMS.map(function(item, i) {
    return '<div class="bdi-item">' +
      '<div class="bdi-pregunta">' + (i+1) + '. ' + item.n + '</div>' +
      '<div class="bdi-opciones">' +
      item.ops.map(function(op, j) {
        return '<label class="bdi-opcion">' +
          '<input type="radio" name="bdi_' + i + '" value="' + j + '">' +
          '<span class="bdi-opcion-texto">' + op + '</span>' +
          '<span class="bdi-score">' + j + '</span>' +
          '</label>';
      }).join('') +
      '</div></div>';
  }).join('');
  document.getElementById('bdi-fecha').value = new Date().toISOString().split('T')[0];
  document.getElementById('bdi-form').style.display = 'block';
  document.getElementById('bdi-resultado').style.display = 'none';
}

function limpiarBDI() {
  if (!confirm('¿Limpiar todos los ítems?')) return;
  document.querySelectorAll('[name^="bdi_"]').forEach(function(r){ r.checked = false; });
}

function calcularBDI() {
  var total = 0; var sinResp = 0;
  for (var i = 0; i < 21; i++) {
    var sel = document.querySelector('[name="bdi_' + i + '"]:checked');
    if (sel) total += parseInt(sel.value);
    else sinResp++;
  }
  if (sinResp > 0) { if (!confirm('Hay ' + sinResp + ' ítem(s) sin respuesta. ¿Continuar de todos modos?')) return; }

  var cat, rango, badge, interp;
  if (total <= 13)      { cat='Mínima';   rango='0–13';  badge='bg-minima';   }
  else if (total <= 19) { cat='Leve';     rango='14–19'; badge='bg-leve';     }
  else if (total <= 28) { cat='Moderada'; rango='20–28'; badge='bg-moderada'; }
  else                  { cat='Grave';    rango='29–63'; badge='bg-grave';    }

  if (total <= 13)
    interp = '<p>El puntaje obtenido ('+total+') se ubica en el rango de <strong>depresión mínima</strong>. No se observan indicadores clínicamente significativos de sintomatología depresiva en el momento de la evaluación.</p>';
  else if (total <= 19)
    interp = '<p>El puntaje obtenido ('+total+') indica un nivel de <strong>depresión leve</strong>. Se recomienda monitorear la evolución de los síntomas y considerar estrategias de intervención temprana.</p>';
  else if (total <= 28)
    interp = '<p>El puntaje obtenido ('+total+') indica un nivel de <strong>depresión moderada</strong>. Los síntomas presentes tienen impacto en el funcionamiento cotidiano. Se recomienda intervención psicológica y/o psiquiátrica.</p>';
  else
    interp = '<p>El puntaje obtenido ('+total+') indica un nivel de <strong>depresión grave</strong>. La intensidad de los síntomas requiere atención clínica inmediata y evaluación de riesgo.</p>';
  interp += '<p><em>Nota: Esta interpretación es orientativa. Debe integrarse con la evaluación clínica completa del profesional.</em></p>';

  document.getElementById('bdi-pts').textContent = total;
  document.getElementById('bdi-cat').textContent = 'Depresión ' + cat;
  document.getElementById('bdi-rango').textContent = 'Rango: ' + rango + ' puntos';
  document.getElementById('bdi-badge').textContent = cat;
  document.getElementById('bdi-badge').className = 'badge-grande ' + badge;
  document.getElementById('bdi-interp').innerHTML = interp;
  document.getElementById('bdi-form').style.display = 'none';
  document.getElementById('bdi-resultado').style.display = 'block';
}

function guardarResultadoBDI() {
  if (!SESSION) return;
  var pacId = document.getElementById('bdi-paciente').value;
  var pts   = parseInt(document.getElementById('bdi-pts').textContent);
  var cat   = document.getElementById('bdi-cat').textContent;
  var fecha = document.getElementById('bdi-fecha').value;
  if (!pacId) { toast('Seleccioná un paciente primero'); return; }
  var iteItems = [];
  document.querySelectorAll('#bdi-items-container .bdi-item').forEach(function(item,i){
    var sel = item.querySelector('input[type=radio]:checked');
    iteItems.push(sel ? parseInt(sel.value) : null);
  });
  var body = { user_id: SESSION.user.id, paciente_id: pacId, test: 'BDI-II', fecha: fecha,
    puntaje_total: pts, categoria: cat,
    datos: { items: iteItems }
  };
  supaFetch('/rest/v1/psico_resultados', 'POST', body, SESSION.access_token)
    .then(function(){
    cargarResultados();
    toast('✓ Resultado guardado', 'success');
    // Animar el botón que estaba activo
    var btnAll = document.querySelectorAll('.vista.active .btn-primary');
    var btn = btnAll.length ? btnAll[btnAll.length-1] : null;
    if(btn){ btn.classList.add('btn-saved'); setTimeout(function(){ btn.classList.remove('btn-saved'); },1500); }
  }).catch(catchGuardarError);
}

