function staiTab(t) {
  document.getElementById('stai-items-e').style.display = t === 'e' ? 'flex' : 'none';
  document.getElementById('stai-items-r').style.display = t === 'r' ? 'flex' : 'none';
  document.getElementById('stai-tab-e').className = 'stai-tab' + (t === 'e' ? ' active' : '');
  document.getElementById('stai-tab-r').className = 'stai-tab' + (t === 'r' ? ' active' : '');
}

function iniciarSTAI() {
  function renderItems(items, prefix, containerId) {
    document.getElementById(containerId).innerHTML = items.map(function(item, i) {
      var labels = ['Nada','Algo','Bastante','Mucho'];
      return '<div class="stai-item">' +
        '<span class="stai-texto">' + (i+1) + '. ' + item.n + '</span>' +
        '<div class="stai-escala">' +
        labels.map(function(lbl, j) {
          return '<label><input type="radio" name="' + prefix + '_' + i + '" value="' + j + '"><span class="stai-escala-lbl">' + lbl + '</span></label>';
        }).join('') +
        '</div></div>';
    }).join('');
  }
  renderItems(STAI_E, 'stai_e', 'stai-items-e');
  renderItems(STAI_R, 'stai_r', 'stai-items-r');
  document.getElementById('stai-fecha').value = new Date().toISOString().split('T')[0];
  document.getElementById('stai-form').style.display = 'block';
  document.getElementById('stai-resultado').style.display = 'none';
  staiTab('e');
}

function limpiarSTAI() {
  if (!confirm('¿Limpiar todos los ítems?')) return;
  document.querySelectorAll('[name^="stai_"]').forEach(function(r){ r.checked = false; });
}

function calcularPuntajeSTAI(items, prefix) {
  var total = 0;
  items.forEach(function(item, i) {
    var sel = document.querySelector('[name="' + prefix + '_' + i + '"]:checked');
    if (!sel) return;
    var v = parseInt(sel.value);
    total += item.inv ? (3 - v) : v;
  });
  return total;
}

function clasificarSTAI(pts, tipo, sexo) {
  var bar = STAI_BAREMOS[tipo][sexo] || STAI_BAREMOS[tipo]['v'];
  if (pts <= bar.p25)      return {cat:'Bajo', badge:'bg-bajo', perc:'≤ p25'};
  else if (pts <= bar.p50) return {cat:'Medio-bajo', badge:'bg-bajo', perc:'p25–p50'};
  else if (pts <= bar.p75) return {cat:'Medio-alto', badge:'bg-medio', perc:'p50–p75'};
  else                     return {cat:'Alto', badge:'bg-alto', perc:'> p75'};
}

function calcularSTAI() {
  var sexo = document.getElementById('stai-sexo').value;
  if (!sexo) { alert('Seleccioná el sexo para aplicar los baremos correctos.'); return; }
  var ptsE = calcularPuntajeSTAI(STAI_E, 'stai_e');
  var ptsR = calcularPuntajeSTAI(STAI_R, 'stai_r');
  var clfE = clasificarSTAI(ptsE, 'e', sexo);
  var clfR = clasificarSTAI(ptsR, 'r', sexo);
  var bar  = STAI_BAREMOS;

  document.getElementById('stai-pts-e').textContent = ptsE;
  document.getElementById('stai-pts-r').textContent = ptsR;
  document.getElementById('stai-badge-e').textContent = 'Estado: ' + clfE.cat;
  document.getElementById('stai-badge-e').className = 'badge-grande ' + clfE.badge;
  document.getElementById('stai-badge-r').textContent = 'Rasgo: ' + clfR.cat;
  document.getElementById('stai-badge-r').className = 'badge-grande ' + clfR.badge;

  var sexoNom = sexo === 'v' ? 'varones' : 'mujeres';
  document.getElementById('stai-percentiles').innerHTML =
    '<div class="detalle-item"><div class="detalle-num">' + ptsE + '</div><div class="detalle-lbl">PD Estado</div></div>' +
    '<div class="detalle-item"><div class="detalle-num">' + clfE.perc + '</div><div class="detalle-lbl">Percentil Estado</div></div>' +
    '<div class="detalle-item"><div class="detalle-num">' + ptsR + '</div><div class="detalle-lbl">PD Rasgo</div></div>' +
    '<div class="detalle-item"><div class="detalle-num">' + clfR.perc + '</div><div class="detalle-lbl">Percentil Rasgo</div></div>' +
    '<div class="detalle-item"><div class="detalle-num">' + sexoNom + '</div><div class="detalle-lbl">Baremo aplicado</div></div>';

  var interp = '';
  interp += '<p><strong>Ansiedad Estado (' + ptsE + ' pts — ' + clfE.cat + '):</strong> ';
  if (clfE.cat === 'Bajo' || clfE.cat === 'Medio-bajo')
    interp += 'La ansiedad situacional al momento de la evaluación se encuentra en niveles bajos, sin indicadores de malestar agudo significativo.';
  else if (clfE.cat === 'Medio-alto')
    interp += 'Se observa un nivel moderado de ansiedad situacional. El evaluado/a experimenta cierto grado de tensión o malestar en el momento actual.';
  else
    interp += 'El nivel de ansiedad situacional es elevado, indicando un estado de activación considerable al momento de la evaluación.';
  interp += '</p>';

  interp += '<p><strong>Ansiedad Rasgo (' + ptsR + ' pts — ' + clfR.cat + '):</strong> ';
  if (clfR.cat === 'Bajo' || clfR.cat === 'Medio-bajo')
    interp += 'La tendencia disposicional a la ansiedad se encuentra dentro de parámetros esperados, sin indicadores de vulnerabilidad ansiosa marcada.';
  else if (clfR.cat === 'Medio-alto')
    interp += 'Se observa una tendencia moderada a percibir situaciones como amenazantes y a responder con estados de ansiedad.';
  else
    interp += 'El nivel de rasgo ansioso es elevado, sugiriendo una tendencia estable a experimentar ansiedad ante una amplia variedad de situaciones.';
  interp += '</p>';

  interp += '<p><em>Baremos: TEA Ediciones (' + sexoNom + '). Clasificación basada en percentiles. Esta interpretación debe integrarse con la evaluación clínica del profesional.</em></p>';
  document.getElementById('stai-interp').innerHTML = interp;

  document.getElementById('stai-form').style.display = 'none';
  document.getElementById('stai-resultado').style.display = 'block';
}

function guardarResultadoSTAI() {
  if (!SESSION) return;
  var pacId = document.getElementById('stai-paciente').value;
  var ptsE  = document.getElementById('stai-pts-e').textContent;
  var ptsR  = document.getElementById('stai-pts-r').textContent;
  var fecha = document.getElementById('stai-fecha').value;
  var catE  = document.getElementById('stai-badge-e').textContent;
  var catR  = document.getElementById('stai-badge-r').textContent;
  if (!pacId) { toast('Seleccioná un paciente primero'); return; }
  var body = {
    user_id: SESSION.user.id, paciente_id: pacId, test: 'STAI', fecha: fecha,
    puntaje_total: parseInt(ptsE),
    categoria: catE + ' / ' + catR,
    detalle: { estado: parseInt(ptsE), rasgo: parseInt(ptsR) },
    datos: { estado: parseInt(ptsE), cat_estado: catE, rasgo: parseInt(ptsR), cat_rasgo: catR }
  };
  supaFetch('/rest/v1/psico_resultados', 'POST', body, SESSION.access_token)
    .then(function(){
    cargarResultados();
    toast('✓ Resultado guardado', 'success');
    // Animar el botón que estaba activo
    var btnAll = document.querySelectorAll('.vista.active .btn-primary');
    var btn = btnAll.length ? btnAll[btnAll.length-1] : null;
    if(btn){ btn.classList.add('btn-saved'); setTimeout(function(){ btn.classList.remove('btn-saved'); },1500); }
  }).catch(catchGuardarError);
}

