var REY_VARS = [
  {key:'t1', label:'Trial I'},
  {key:'t2', label:'Trial II'},
  {key:'t3', label:'Trial III'},
  {key:'t4', label:'Trial IV'},
  {key:'t5', label:'Trial V'},
  {key:'sum',label:'Sumatoria'},
  {key:'lb', label:'Lista B'},
  {key:'t6', label:'Trial VI (CP)'},
  {key:'t7', label:'Trial VII (LP)'},
  {key:'rec',label:'Reconocimiento'}
];

function iniciarRey() {
  document.getElementById('rey-fecha').value = new Date().toISOString().split('T')[0];
  document.getElementById('rey-form').style.display = 'block';
  document.getElementById('rey-resultado').style.display = 'none';
  llenarSelectRey();
}

function llenarSelectRey() {
  var opts = '<option value="">— Seleccionar paciente —</option>' +
    PACIENTES.map(function(p){ return '<option value="' + p.id + '">' + escHtml(p.nombre) + '</option>'; }).join('');
  document.getElementById('rey-paciente').innerHTML = opts;
}

function limpiarRey() {
  if (!confirm('¿Limpiar todos los datos?')) return;
  ['rey-t1','rey-t2','rey-t3','rey-t4','rey-t5','rey-sum','rey-lb','rey-t6','rey-t7','rey-rec'].forEach(function(id){
    document.getElementById(id).value = '';
  });
}

function calcularRey() {
  var sexo = document.getElementById('rey-sexo').value;
  var gIdx = document.getElementById('rey-edad').value;
  if (!sexo || gIdx === '') { alert('Seleccioná sexo y grupo de edad.'); return; }
  var gi = parseInt(gIdx);
  var bar = REY_BAR[sexo];
  var grupoLabel = document.getElementById('rey-edad').selectedOptions[0].text;
  var sexoLabel  = sexo === 'h' ? 'Hombre' : 'Mujer';

  document.getElementById('rey-res-meta').textContent = sexoLabel + ' · ' + grupoLabel;

  var html = '';
  var cN=0, cL=0, cM=0, cB=0;
  var zVals = {};

  REY_VARS.forEach(function(v) {
    var inputId = 'rey-' + v.key;
    var el = document.getElementById(inputId);
    var raw = el ? el.value : '';
    if (raw === '') {
      html += '<tr><td style="padding:8px 12px;font-size:0.84rem;">' + v.label + '</td>' +
        '<td colspan="4" style="text-align:center;padding:8px 12px;color:var(--muted);font-size:0.82rem;">—</td>' +
        '<td style="text-align:center;padding:8px 12px;"><span class="badge badge-nd" style="background:var(--surface2);color:var(--muted);">Sin datos</span></td></tr>';
      return;
    }
    var bruto = parseFloat(raw);
    var b = bar[v.key][gi];
    var z = (bruto - b.m) / b.d;
    zVals[v.key] = z;

    var clf, col;
    if (z >= -1.0)      { clf = 'Normal';     col = 'var(--green)';  cN++; }
    else if (z >= -1.5) { clf = 'Leve ↓';     col = 'var(--yellow)'; cL++; }
    else if (z >= -2.0) { clf = 'Moderado ↓'; col = 'var(--orange)'; cM++; }
    else                { clf = 'Bajo ↓';     col = 'var(--red)';    cB++; }

    var badgeClass = z >= -1.0 ? 'badge-normal' : z >= -1.5 ? 'badge-leve' : z >= -2.0 ? 'badge-moderado' : 'badge-bajo';

    html += '<tr style="border-bottom:1px solid var(--border);">' +
      '<td style="padding:8px 12px;font-size:0.84rem;font-weight:500;">' + v.label + '</td>' +
      '<td style="padding:8px 12px;text-align:center;font-family:\'DM Mono\',monospace;">' + bruto + '</td>' +
      '<td style="padding:8px 12px;text-align:center;font-family:\'DM Mono\',monospace;color:var(--muted);">' + b.m + '</td>' +
      '<td style="padding:8px 12px;text-align:center;font-family:\'DM Mono\',monospace;color:var(--muted);">' + b.d + '</td>' +
      '<td style="padding:8px 12px;text-align:center;font-family:\'DM Mono\',monospace;font-weight:600;color:' + col + ';">' + (z >= 0 ? '+' : '') + z.toFixed(2) + '</td>' +
      '<td style="padding:8px 12px;text-align:center;"><span class="badge ' + badgeClass + '">' + clf + '</span></td>' +
      '</tr>';
  });

  document.getElementById('rey-tabla-body').innerHTML = html;

  // Interpretación
  var ps = [];
  if (zVals.sum !== undefined) {
    if (zVals.sum >= -1.0)
      ps.push('El rendimiento en aprendizaje verbal total (Sumatoria I–V) se encuentra dentro de los parámetros esperados para ' + sexoLabel + ', ' + grupoLabel + ' (Z=' + zVals.sum.toFixed(2) + ').');
    else if (zVals.sum >= -1.5)
      ps.push('Se observa un rendimiento levemente por debajo de lo esperado en aprendizaje verbal total (Z=' + zVals.sum.toFixed(2) + ') para ' + sexoLabel + ', ' + grupoLabel + '.');
    else if (zVals.sum >= -2.0)
      ps.push('El rendimiento en aprendizaje verbal es moderadamente bajo (Z=' + zVals.sum.toFixed(2) + '), sugiriendo dificultades en la adquisición de nueva información verbal.');
    else
      ps.push('Se evidencia un rendimiento significativamente bajo en aprendizaje verbal (Z=' + zVals.sum.toFixed(2) + '), indicando dificultades marcadas en la adquisición de nueva información.');
  }
  if (zVals.t6 !== undefined && zVals.t7 !== undefined) {
    if (zVals.t6 >= -1.0 && zVals.t7 >= -1.0)
      ps.push('Los procesos de memoria verbal a corto plazo (Trial VI: Z=' + zVals.t6.toFixed(2) + ') y largo plazo (Trial VII: Z=' + zVals.t7.toFixed(2) + ') se encuentran preservados.');
    else if (zVals.t6 < -1.0 || zVals.t7 < -1.0)
      ps.push('Se observan dificultades en la memoria demorada: corto plazo (Trial VI: Z=' + zVals.t6.toFixed(2) + '), largo plazo (Trial VII: Z=' + zVals.t7.toFixed(2) + ').');
  }
  if (zVals.rec !== undefined) {
    if (zVals.rec >= -1.0)
      ps.push('El reconocimiento verbal se encuentra preservado (Z=' + zVals.rec.toFixed(2) + ').');
    else
      ps.push('El reconocimiento verbal es bajo (Z=' + zVals.rec.toFixed(2) + '), lo que podría indicar compromisos en el almacenamiento.');
  }
  if (!ps.length) ps.push('Complete los puntajes principales para obtener una síntesis interpretativa.');
  ps.push('<em>Nota: Esta síntesis es orientativa y debe integrarse con el juicio clínico del profesional.</em>');
  document.getElementById('rey-interp').innerHTML = ps.map(function(p){ return '<p>'+p+'</p>'; }).join('');

  document.getElementById('rey-form').style.display = 'none';
  document.getElementById('rey-resultado').style.display = 'block';
}

function guardarResultadoRey() {
  if (!SESSION) return;
  var pacId = document.getElementById('rey-paciente').value;
  var fecha = document.getElementById('rey-fecha').value;
  var sum   = document.getElementById('rey-sum').value;
  if (!pacId) { toast('Seleccioná un paciente primero'); return; }
  var sexo=document.getElementById('rey-sexo').value;
  var edadI=document.getElementById('rey-edad').value;
  var datosObj={sexo:sexo,edad_grupo:edadI,variables:[]};
  var zSum=null;
  if(sexo&&edadI!==''){
    var gi=parseInt(edadI);
    REY_VARS.forEach(function(v){
      var el=document.getElementById('rey-'+v.key); if(!el)return;
      var raw=el.value; if(raw==='')return;
      var bruto=parseFloat(raw);
      var barArr=REY_BAR[sexo][v.key]; if(!barArr||!barArr[gi])return; var bar=barArr[gi];
      var z=parseFloat(((bruto-bar.m)/bar.d).toFixed(2));
      datosObj.variables.push({key:v.key,label:v.label,bruto:bruto,m:bar.m,ds:bar.d,z:z});
      if(v.key==='sum') zSum=z;
    });
  }
  var catRey = zSum===null ? 'Ver detalle' : (zSum>=-1.0?'Normal':zSum>=-1.5?'Leve ↓':zSum>=-2.0?'Moderado ↓':'Bajo ↓');
  var body = {
    user_id: SESSION.user.id, paciente_id: pacId, test: 'Rey Verbal',
    fecha: fecha, puntaje_total: sum ? parseInt(sum) : null,
    categoria: catRey, puntaje_z: zSum,
    puntaje_t: zSum!==null ? parseFloat((50+10*zSum).toFixed(1)) : null,
    percentil: zSum!==null ? Math.max(1,Math.min(99,Math.round(50+28.57*zSum))) : null,
    datos: datosObj
  };
  supaFetch('/rest/v1/psico_resultados', 'POST', body, SESSION.access_token)
    .then(function(){
    cargarResultados();
    toast('✓ Resultado guardado', 'success');
    // Animar el botón que estaba activo
    var btnAll = document.querySelectorAll('.vista.active .btn-primary');
    var btn = btnAll.length ? btnAll[btnAll.length-1] : null;
    if(btn){ btn.classList.add('btn-saved'); setTimeout(function(){ btn.classList.remove('btn-saved'); },1500); }
  }).catch(catchGuardarError);
}

