function limpiarSignoret() {
  if (!confirm('¿Limpiar todos los datos?')) return;
  SIGNORET_KEYS.map(function(k){ return 'sig-' + k; }).forEach(function(id){
    document.getElementById(id).value = '';
  });
}

function calcularSignoret() {
  var giStr = document.getElementById('signoret-edad').value;
  if (giStr === '') { toast('Seleccioná el grupo de edad', 'error'); return; }
  var gi = parseInt(giStr, 10);

  var html = '<table style="width:100%;border-collapse:collapse;">' +
    '<thead><tr>' +
    '<th style="text-align:left;padding:8px 12px;font-size:0.8rem;color:var(--muted);">Subprueba</th>' +
    '<th style="padding:8px 12px;font-size:0.8rem;color:var(--muted);">PB</th>' +
    '<th style="padding:8px 12px;font-size:0.8rem;color:var(--muted);">M</th>' +
    '<th style="padding:8px 12px;font-size:0.8rem;color:var(--muted);">DS</th>' +
    '<th style="padding:8px 12px;font-size:0.8rem;color:var(--muted);">Z</th>' +
    '<th style="padding:8px 12px;font-size:0.8rem;color:var(--muted);">Interpretación</th>' +
    '</tr></thead><tbody>';
  var zSum = 0, zCount = 0;
  var raws = {};
  SIGNORET_KEYS.forEach(function(k) {
    var el = document.getElementById('sig-' + k);
    var raw = el ? el.value : '';
    var bar = SIGNORET_BAR[k];
    if (raw === '') {
      html += '<tr><td style="padding:8px 12px;font-size:0.84rem;">' + bar.label + '</td>' +
        '<td colspan="4" style="text-align:center;padding:8px 12px;color:var(--muted);font-size:0.82rem;">—</td>' +
        '<td style="text-align:center;padding:8px 12px;color:var(--muted);font-size:0.82rem;">Sin datos</td></tr>';
      return;
    }
    var bruto = parseFloat(raw);
    raws[k] = bruto;
    var m = bar.M[gi], ds = bar.DS[gi];
    var z = parseFloat(((bruto - m) / ds).toFixed(2));
    zSum += z; zCount++;
    var meta = zNormMeta(z, false);
    html += '<tr style="border-bottom:1px solid var(--border);">' +
      '<td style="padding:8px 12px;font-size:0.84rem;font-weight:500;">' + bar.label + '</td>' +
      '<td style="padding:8px 12px;text-align:center;font-family:\'DM Mono\',monospace;">' + bruto + '</td>' +
      '<td style="padding:8px 12px;text-align:center;font-family:\'DM Mono\',monospace;color:var(--muted);">' + m.toFixed(2) + '</td>' +
      '<td style="padding:8px 12px;text-align:center;font-family:\'DM Mono\',monospace;color:var(--muted);">' + ds.toFixed(2) + '</td>' +
      '<td style="padding:8px 12px;text-align:center;font-family:\'DM Mono\',monospace;font-weight:600;color:' + meta.color + ';">' + (z >= 0 ? '+' : '') + z.toFixed(2) + '</td>' +
      '<td style="padding:8px 12px;text-align:center;color:' + meta.color + ';font-weight:600;">' + meta.label + '</td>' +
      '</tr>';
  });
  html += '</tbody></table>';
  if (raws.rc !== undefined && raws.reco !== undefined) {
    var recCe = (raws.rc + raws.reco) / 2;
    html += '<p style="font-size:0.8rem;color:var(--muted);margin-top:10px;">Rec-CE (promedio Claves + Reconocimiento): <strong>' + recCe.toFixed(1) + '</strong> (valor descriptivo, sin baremo propio).</p>';
  }
  document.getElementById('signoret-detalle').innerHTML = html;

  var zProm = zCount ? parseFloat((zSum / zCount).toFixed(2)) : null;
  window._signoretData = { gi: gi, zProm: zProm };

  var interp;
  if (zProm === null) {
    interp = '<p>Completá al menos una subprueba para obtener una interpretación.</p>';
  } else {
    var metaProm = zNormMeta(zProm, false);
    interp = '<p>El promedio de Z de las subpruebas completadas (Z=' + (zProm >= 0 ? '+' : '') + zProm.toFixed(2) + ') se ubica en el rango <strong>' + metaProm.label + '</strong>.</p>' +
      '<p><em>Nota: este promedio es una síntesis orientativa. Se recomienda analizar el perfil por subprueba (memoria lógica verbal vs. memoria episódica verbal) y contrastarlo con TAVEC y Figura de Rey.</em></p>';
  }
  document.getElementById('signoret-interp').innerHTML = interp;

  document.getElementById('signoret-form').style.display = 'none';
  document.getElementById('signoret-resultado').style.display = 'block';
}

function guardarResultadoSignoret() {
  if (!SESSION) return;
  var pacId = document.getElementById('signoret-paciente').value;
  var fecha = document.getElementById('signoret-fecha').value;
  var giStr = document.getElementById('signoret-edad').value;
  if (!pacId) { toast('Seleccioná un paciente primero'); return; }
  var datosObj = { grupo_edad: giStr !== '' ? parseInt(giStr, 10) : null };
  var total = 0, totalCount = 0;
  SIGNORET_KEYS.forEach(function(k) {
    var el = document.getElementById('sig-' + k);
    var raw = el ? el.value : '';
    if (raw === '') return;
    var v = parseFloat(raw);
    datosObj[k] = v;
    total += v; totalCount++;
  });
  var zProm = (window._signoretData && window._signoretData.zProm !== undefined) ? window._signoretData.zProm : null;
  var catSignoret = zProm === null ? 'Ver detalle' : zNormMeta(zProm, false).label;
  var body = {
    user_id: SESSION.user.id, paciente_id: pacId, test: 'BEM 144 Signoret',
    fecha: fecha, puntaje_total: totalCount ? total : null,
    categoria: catSignoret, puntaje_z: zProm,
    puntaje_t: zProm !== null ? parseFloat((50 + 10 * zProm).toFixed(1)) : null,
    percentil: zProm !== null ? Math.max(1, Math.min(99, Math.round(50 + 28.57 * zProm))) : null,
    datos: datosObj
  };
  supaFetch('/rest/v1/psico_resultados', 'POST', body, SESSION.access_token)
    .then(function(){
      cargarResultados();
      toast('✓ Resultado guardado', 'success');
      var btnAll = document.querySelectorAll('.vista.active .btn-primary');
      var btn = btnAll.length ? btnAll[btnAll.length-1] : null;
      if (btn) { btn.classList.add('btn-saved'); setTimeout(function(){ btn.classList.remove('btn-saved'); }, 1500); }
    }).catch(catchGuardarError);
}

// ══ TMT — BAREMOS ════════════════════════════════════════════════════════════
// Fernández, Marino & Alderete (2002) — Rev. Neurológica Argentina 27(2):83-88
// n=251 · Córdoba · 15–70 años · más tiempo = peor · Z = (M − bruto) / DS

var TMT_ARG_REF = 'Fernández, Marino & Alderete (2002) — Revista Neurológica Argentina, 27(2), 83–88. n=251, adultos argentinos 15–70 años, Córdoba.';

var TMT_ARG_2002 = {
  joven: {
    a: {
      primario:   {m:62,    ds:14.98},
      secundario: {m:44.47, ds:17.32},
      terciario:  {m:37.4,  ds:10.77}
    },
    b: {
      primario: {
        calificados:    {m:112.2, ds:48},
        no_calificados: {m:128.9, ds:23.1}
      },
      secundario: {
        profesionales:  {m:73.4,  ds:16.9},
        calificados:    {m:91.5,  ds:26.5},
        no_calificados: {m:108,   ds:55.5}
      },
      terciario: {
        profesionales: {m:66.4, ds:18.14},
        calificados:   {m:74.4, ds:16.4}
      }
    }
  },
  mayor: {
    a: {
      bajo: {m:73.68, ds:30.84},
      alto: {m:47.89, ds:11.33}
    },
    b: {
      bajo: {m:160.5,  ds:59.72},
      alto: {m:103.67, ds:29.92}
    }
  }
};

function tmtZ(bruto, m, ds) {
  return (m - bruto) / ds;
}

function tmtPercentil(z) {
  return Math.max(1, Math.min(99, Math.round(50 + 28.57 * z)));
}

function tmtBaremoA(edadG, escol) {
  return TMT_ARG_2002[edadG].a[escol];
}

function tmtBaremoB(edadG, escol, ocup) {
  if (edadG === 'mayor') return TMT_ARG_2002.mayor.b[escol];
  return TMT_ARG_2002.joven.b[escol][ocup];
}

function tmtActualizarForm() {
  var edad = document.getElementById('tmt-edad').value;
  var escolSel = document.getElementById('tmt-escol');
  var ocupField = document.getElementById('tmt-ocup-field');
  if (!escolSel) return;
  if (edad === 'joven') {
    escolSel.innerHTML =
      '<option value="">— Seleccionar —</option>' +
      '<option value="primario">Primario (0–6 años)</option>' +
      '<option value="secundario">Secundario (7–12 años)</option>' +
      '<option value="terciario">Terciario (13+ años)</option>';
    if (ocupField) ocupField.style.display = '';
  } else if (edad === 'mayor') {
    escolSel.innerHTML =
      '<option value="">— Seleccionar —</option>' +
      '<option value="bajo">Bajo (0–12 años)</option>' +
      '<option value="alto">Alto (más de 12 años)</option>';
    if (ocupField) ocupField.style.display = 'none';
  } else {
    escolSel.innerHTML = '<option value="">— Seleccionar edad primero —</option>';
    if (ocupField) ocupField.style.display = 'none';
  }
  tmtActualizarOcup();
}

function tmtActualizarOcup() {
  var edad = document.getElementById('tmt-edad').value;
  var escol = document.getElementById('tmt-escol').value;
  var ocupSel = document.getElementById('tmt-ocup');
  if (!ocupSel) return;
  if (edad !== 'joven') {
    ocupSel.innerHTML = '<option value="">— No aplica (60–70 años) —</option>';
    return;
  }
  var opts = '<option value="">— Seleccionar —</option>';
  if (escol === 'primario') {
    opts += '<option value="calificados">Empleados calificados</option>';
    opts += '<option value="no_calificados">Empleados no calificados</option>';
  } else if (escol === 'secundario') {
    opts += '<option value="profesionales">Profesionales / Estudiantes</option>';
    opts += '<option value="calificados">Empleados calificados</option>';
    opts += '<option value="no_calificados">Empleados no calificados</option>';
  } else if (escol === 'terciario') {
    opts += '<option value="profesionales">Profesionales / Estudiantes</option>';
    opts += '<option value="calificados">Empleados calificados</option>';
  } else {
    opts = '<option value="">— Seleccionar escolaridad —</option>';
  }
  ocupSel.innerHTML = opts;
}

function clasificarTMT(z) {
  // Z INVERTIDO: negativo = más lento = déficit (igual que el resto de los tests)
  if (z >= -1.0)       return {clf:'Normal',          col:'var(--green)',  badge:'bg-minima'};
  else if (z >= -1.5)  return {clf:'Leve ↓',          col:'var(--yellow)', badge:'bg-leve'};
  else if (z >= -2.0)  return {clf:'Moderado ↓',      col:'var(--orange)', badge:'bg-moderada'};
  else                 return {clf:'Bajo ↓ (déficit)', col:'var(--red)',    badge:'bg-grave'};
}

function iniciarTMT() {
  document.getElementById('tmt-fecha').value = new Date().toISOString().split('T')[0];
  document.getElementById('tmt-form').style.display = 'block';
  document.getElementById('tmt-resultado').style.display = 'none';
  tmtActualizarForm();
  var opts = '<option value="">— Seleccionar paciente —</option>' +
    PACIENTES.map(function(p){ return '<option value="' + p.id + '">' + escHtml(p.nombre) + '</option>'; }).join('');
  document.getElementById('tmt-paciente').innerHTML = opts;
}

function limpiarTMT() {
  document.getElementById('tmt-a').value = '';
  document.getElementById('tmt-b').value = '';
}

function calcularTMT() {
  var edadG  = document.getElementById('tmt-edad').value;
  var escol  = document.getElementById('tmt-escol').value;
  var ocup   = document.getElementById('tmt-ocup').value;
  var tA     = document.getElementById('tmt-a').value;
  var tB     = document.getElementById('tmt-b').value;

  if (!edadG) { alert('Seleccioná el grupo de edad.'); return; }
  if (!escol) { alert('Seleccioná el nivel de escolaridad.'); return; }
  if (edadG === 'joven' && tB !== '' && !ocup) { alert('Seleccioná la ocupación para TMT-B (15–59 años).'); return; }
  if (!tA && !tB) { alert('Ingresá al menos uno de los tiempos.'); return; }

  var edadLabel = document.getElementById('tmt-edad').selectedOptions[0].text;
  var escolLabel = document.getElementById('tmt-escol').selectedOptions[0].text;
  var metaParts = [edadLabel, escolLabel];
  if (edadG === 'joven' && ocup) metaParts.push(document.getElementById('tmt-ocup').selectedOptions[0].text);
  document.getElementById('tmt-res-meta').textContent = metaParts.join(' · ');

  var cards = '';
  var interpA = '', interpB = '';

  // ── TMT-A ──
  if (tA !== '') {
    var brutoA = parseFloat(tA);
    var mdsA   = tmtBaremoA(edadG, escol);
    var zA     = tmtZ(brutoA, mdsA.m, mdsA.ds);
    var pcA    = tmtPercentil(zA);
    var clfA   = clasificarTMT(zA);

    cards += '<div style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:20px 22px;">' +
      '<div style="font-size:0.72rem;font-weight:700;text-transform:uppercase;letter-spacing:1px;color:var(--accent);margin-bottom:10px;">TMT — Parte A</div>' +
      '<div style="display:flex;align-items:baseline;gap:8px;margin-bottom:8px;">' +
        '<span style="font-family:\'DM Mono\',monospace;font-size:2.2rem;font-weight:600;color:var(--accentdk);">' + brutoA + '</span>' +
        '<span style="font-size:0.82rem;color:var(--muted);">seg</span>' +
      '</div>' +
      '<div style="display:flex;gap:16px;margin-bottom:10px;">' +
        '<div><div style="font-size:0.7rem;color:var(--muted);text-transform:uppercase;">Percentil</div>' +
        '<div style="font-family:\'DM Mono\',monospace;font-size:1.5rem;font-weight:600;color:var(--text);">' + pcA + '</div></div>' +
        '<div><div style="font-size:0.7rem;color:var(--muted);text-transform:uppercase;">Z</div>' +
        '<div style="font-family:\'DM Mono\',monospace;font-size:1.5rem;font-weight:600;color:' + clfA.col + ';">' + (zA >= 0 ? '+' : '') + zA.toFixed(2) + '</div></div>' +
      '</div>' +
      '<span class="badge-grande ' + clfA.badge + '">' + clfA.clf + '</span>' +
      '<div style="font-size:0.76rem;color:var(--muted);margin-top:8px;">M=' + mdsA.m + ' · DS=' + mdsA.ds + '</div>' +
      '</div>';

    if (zA >= -1.0)
      interpA = 'TMT-A: El tiempo de ejecución (' + brutoA + ' seg, PC=' + pcA + ') se encuentra dentro de los parámetros esperados para su grupo. No se observan indicadores de compromiso en la velocidad de procesamiento ni en la atención sostenida.';
    else if (zA >= -1.5)
      interpA = 'TMT-A: El tiempo de ejecución (' + brutoA + ' seg, PC=' + pcA + ') es levemente más lento de lo esperado, sugiriendo un posible compromiso leve en la velocidad de procesamiento o la atención sostenida.';
    else if (zA >= -2.0)
      interpA = 'TMT-A: Se observa un tiempo de ejecución moderadamente elevado (' + brutoA + ' seg, PC=' + pcA + '), indicando dificultades en la velocidad de procesamiento y/o la atención sostenida.';
    else
      interpA = 'TMT-A: El tiempo de ejecución es significativamente alto (' + brutoA + ' seg, PC=' + pcA + '), indicando un déficit marcado en la velocidad de procesamiento y la atención sostenida.';
  }

  // ── TMT-B ──
  if (tB !== '') {
    var brutoB = parseFloat(tB);
    var mdsB   = tmtBaremoB(edadG, escol, ocup);
    var zB     = tmtZ(brutoB, mdsB.m, mdsB.ds);
    var pcB    = tmtPercentil(zB);
    var clfB   = clasificarTMT(zB);

    cards += '<div style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:20px 22px;">' +
      '<div style="font-size:0.72rem;font-weight:700;text-transform:uppercase;letter-spacing:1px;color:var(--accent);margin-bottom:10px;">TMT — Parte B</div>' +
      '<div style="display:flex;align-items:baseline;gap:8px;margin-bottom:8px;">' +
        '<span style="font-family:\'DM Mono\',monospace;font-size:2.2rem;font-weight:600;color:var(--accentdk);">' + brutoB + '</span>' +
        '<span style="font-size:0.82rem;color:var(--muted);">seg</span>' +
      '</div>' +
      '<div style="display:flex;gap:16px;margin-bottom:10px;">' +
        '<div><div style="font-size:0.7rem;color:var(--muted);text-transform:uppercase;">Percentil</div>' +
        '<div style="font-family:\'DM Mono\',monospace;font-size:1.5rem;font-weight:600;color:var(--text);">' + pcB + '</div></div>' +
        '<div><div style="font-size:0.7rem;color:var(--muted);text-transform:uppercase;">Z</div>' +
        '<div style="font-family:\'DM Mono\',monospace;font-size:1.5rem;font-weight:600;color:' + clfB.col + ';">' + (zB >= 0 ? '+' : '') + zB.toFixed(2) + '</div></div>' +
      '</div>' +
      '<span class="badge-grande ' + clfB.badge + '">' + clfB.clf + '</span>' +
      '<div style="font-size:0.76rem;color:var(--muted);margin-top:8px;">M=' + mdsB.m + ' · DS=' + mdsB.ds + '</div>' +
      '</div>';

    if (zB >= -1.0)
      interpB = 'TMT-B: El tiempo de ejecución (' + brutoB + ' seg, PC=' + pcB + ') es normal para su grupo. No se evidencian compromisos en la atención alternante ni en la flexibilidad cognitiva.';
    else if (zB >= -1.5)
      interpB = 'TMT-B: El tiempo es levemente más lento de lo esperado (' + brutoB + ' seg, PC=' + pcB + '), sugiriendo una posible dificultad leve en la atención alternante y/o la flexibilidad cognitiva.';
    else if (zB >= -2.0)
      interpB = 'TMT-B: Se observa lentitud moderada en la ejecución (' + brutoB + ' seg, PC=' + pcB + '), indicando compromisos en la flexibilidad cognitiva y la atención alternante.';
    else
      interpB = 'TMT-B: El tiempo de ejecución es significativamente elevado (' + brutoB + ' seg, PC=' + pcB + '), sugiriendo un déficit marcado en la atención alternante, la flexibilidad cognitiva y/o las funciones ejecutivas.';
  }

  document.getElementById('tmt-res-cards').innerHTML = cards;
  var interp = '';
  if (interpA) interp += '<p>' + interpA + '</p>';
  if (interpB) interp += '<p>' + interpB + '</p>';
  interp += '<p><em>Baremo: ' + TMT_ARG_REF + ' Esta interpretación es orientativa y debe integrarse con el juicio clínico del profesional.</em></p>';
  document.getElementById('tmt-interp').innerHTML = interp;

  document.getElementById('tmt-form').style.display = 'none';
  document.getElementById('tmt-resultado').style.display = 'block';
}

function guardarResultadoTMT() {
  if (!SESSION) return;
  var pacId = document.getElementById('tmt-paciente').value;
  var fecha = document.getElementById('tmt-fecha').value;
  var tA    = document.getElementById('tmt-a').value;
  var tB    = document.getElementById('tmt-b').value;
  var edadG = document.getElementById('tmt-edad').value;
  var escol = document.getElementById('tmt-escol').value;
  var ocup  = document.getElementById('tmt-ocup').value;
  if (!pacId) { toast('Seleccioná un paciente primero'); return; }
  var cat = 'A:' + (tA||'—') + 's / B:' + (tB||'—') + 's';
  var datosObj = {
    tmt_a_seg: tA ? parseFloat(tA) : null,
    tmt_b_seg: tB ? parseFloat(tB) : null,
    tmt_edad_grupo: edadG || null,
    tmt_escol: escol || null,
    tmt_ocup: ocup || null,
    tmt_baremo: 'Fernández, Marino & Alderete (2002)'
  };
  if (edadG && escol) {
    if (tA !== '') {
      var mdsA = tmtBaremoA(edadG, escol);
      datosObj.tmt_a_z = parseFloat(tmtZ(parseFloat(tA), mdsA.m, mdsA.ds).toFixed(2));
      datosObj.tmt_a_m = mdsA.m; datosObj.tmt_a_ds = mdsA.ds;
    }
    if (tB !== '' && (edadG === 'mayor' || ocup)) {
      var mdsB = tmtBaremoB(edadG, escol, ocup);
      datosObj.tmt_b_z = parseFloat(tmtZ(parseFloat(tB), mdsB.m, mdsB.ds).toFixed(2));
      datosObj.tmt_b_m = mdsB.m; datosObj.tmt_b_ds = mdsB.ds;
    }
  }
  var zPrincipal = datosObj.tmt_b_z !== undefined ? datosObj.tmt_b_z : (datosObj.tmt_a_z !== undefined ? datosObj.tmt_a_z : null);
  var body = { user_id: SESSION.user.id, paciente_id: pacId, test: 'TMT A-B', fecha: fecha,
    puntaje_total: null, categoria: cat,
    puntaje_z: zPrincipal,
    puntaje_t: zPrincipal!==null ? parseFloat((50+10*zPrincipal).toFixed(1)) : null,
    percentil: zPrincipal!==null ? Math.max(1,Math.min(99,Math.round(50+28.57*zPrincipal))) : null,
    datos: datosObj
  };
  supaFetch('/rest/v1/psico_resultados', 'POST', body, SESSION.access_token)
    .then(function(){
    cargarResultados();
    toast('✓ Resultado guardado', 'success');
    // Animar el botón que estaba activo
    var btnAll = document.querySelectorAll('.vista.active .btn-primary');
    var btn = btnAll.length ? btnAll[btnAll.length-1] : null;
    if(btn){ btn.classList.add('btn-saved'); setTimeout(function(){ btn.classList.remove('btn-saved'); },1500); }
  }).catch(catchGuardarError);
}

// ── Etiquetas simplificadas informe (Apéndice B Word/PDF) ──
var SINT_AUS = 'Ausencia de sintomatología';
var SINT_SIG = 'Sintomatología significativa';

function informeBdiResultado(puntaje, categoria) {
  if (puntaje != null && !isNaN(parseFloat(puntaje))) {
    return parseFloat(puntaje) <= 19 ? SINT_AUS : SINT_SIG;
  }
  var c = String(categoria || '').toLowerCase();
  if (/grave|moderad/.test(c)) return SINT_SIG;
  if (/m[ií]nim|leve/.test(c)) return SINT_AUS;
  return categoria || '—';
}

function informeStaiResultado(catStr) {
  if (!catStr) return '—';
  var c = String(catStr).replace(/^(Estado|Rasgo):\s*/i, '').trim().toLowerCase();
  if (c === 'alto' || c === 'medio-alto') return SINT_SIG;
  if (c === 'bajo' || c === 'medio-bajo') return SINT_AUS;
  return '—';
}

function informeHolmesEstresores(total, categoria) {
  if (total != null && !isNaN(parseFloat(total))) {
    var t = parseFloat(total);
    if (t < 180) return 'Estresores leves';
    if (t <= 320) return 'Estresores moderados';
    return 'Estresores severos';
  }
  var c = String(categoria || '').toLowerCase();
  if (/bajo/.test(c)) return 'Estresores leves';
  if (/intermedio|moderado/.test(c)) return 'Estresores moderados';
  if (/alto|severo/.test(c)) return 'Estresores severos';
  return '—';
}

function informeAsrsSecA(pos) {
  if (pos == null || isNaN(parseFloat(pos))) return '—';
  return parseFloat(pos) >= 4 ? SINT_SIG : SINT_AUS;
}

function informeAsrsSubescala(pc, z) {
  if (pc != null && !isNaN(parseFloat(pc))) {
    return parseFloat(pc) >= 75 ? SINT_SIG : SINT_AUS;
  }
  if (z != null && !isNaN(parseFloat(z))) {
    return parseFloat(z) >= 0.67 ? SINT_SIG : SINT_AUS;
  }
  return '—';
}

function informeWursResultado(total, categoria) {
  if (total != null && !isNaN(parseFloat(total))) {
    return parseFloat(total) >= 36 ? SINT_SIG : SINT_AUS;
  }
  var c = String(categoria || '').toLowerCase();
  if (/significativ|probable|compatible/.test(c)) return SINT_SIG;
  if (/sin s[ií]ntomas/.test(c)) return SINT_AUS;
  return '—';
}

function informeEavaResultado(catStr, score) {
  if (score != null && !isNaN(parseFloat(score))) {
    return parseFloat(score) >= 17 ? SINT_SIG : SINT_AUS;
  }
  var c = String(catStr || '').toLowerCase();
  if (/muy probable|probable/.test(c)) return SINT_SIG;
  if (/baja probabilidad|sin|no significativ/.test(c)) return SINT_AUS;
  return '—';
}

function informeTdahBinario(categoria) {
  var c = String(categoria || '').toLowerCase();
  if (/significativ|positiv|probable|compatible|elev|alter|deficit|grave|moderad/.test(c)) return SINT_SIG;
  if (/sin s[ií]ntomas|negativ|bajo|normal|preserv|ausencia/.test(c)) return SINT_AUS;
  return categoria || '—';
}

