var FLV_VARS = [
  {key:'animales', id:'flv-animales', label:'Fluencia verbal semántica (animales)', tipo:'Semántica'},
  {key:'frutas',   id:'flv-frutas',   label:'Frutas',   tipo:'Semántica'},
  {key:'letraP',   id:'flv-p',        label:'Fluencia fonológica (letra P)',  tipo:'Fonológica'},
  {key:'letraF',   id:'flv-f',        label:'Letra F',  tipo:'Fonológica'}
];

function iniciarFLV() {
  document.getElementById('flv-fecha').value = new Date().toISOString().split('T')[0];
  document.getElementById('flv-form').style.display = 'block';
  document.getElementById('flv-resultado').style.display = 'none';
  var opts = '<option value="">— Seleccionar paciente —</option>' +
    PACIENTES.map(function(p){ return '<option value="' + p.id + '">' + escHtml(p.nombre) + '</option>'; }).join('');
  document.getElementById('flv-paciente').innerHTML = opts;
}

function limpiarFLV() {
  FLV_VARS.forEach(function(v){ document.getElementById(v.id).value = ''; });
}

function calcularFLV() {
  var sexo  = document.getElementById('flv-sexo').value;
  var ne    = document.getElementById('flv-ne').value;
  var edadI = document.getElementById('flv-edad').value;
  if (!sexo || !ne || edadI === '') { alert('Completá sexo, nivel educativo y grupo de edad.'); return; }

  var gi = parseInt(edadI);
  var sexoLabel  = sexo === 'v' ? 'Varón' : 'Mujer';
  var neLabel    = ne === 'alto' ? 'NE Alto' : 'NE Bajo';
  var edadLabel  = document.getElementById('flv-edad').selectedOptions[0].text;
  document.getElementById('flv-res-meta').textContent = sexoLabel + ' · ' + neLabel + ' · ' + edadLabel;

  var html = '';
  var tipoActual = '';
  var zSem = [], zFon = [];
  var algunoDato = false;

  FLV_VARS.forEach(function(v) {
    var raw = document.getElementById(v.id).value;

    // separador de tipo
    if (v.tipo !== tipoActual) {
      tipoActual = v.tipo;
      html += '<tr><td colspan="6" style="padding:10px 12px 4px;font-size:0.7rem;font-weight:700;text-transform:uppercase;letter-spacing:1px;color:var(--accent);border-bottom:1px solid var(--border);">' + tipoActual + '</td></tr>';
    }

    if (raw === '') {
      html += '<tr><td style="padding:7px 12px;font-size:0.84rem;color:var(--muted);">' + v.label + '</td>' +
        '<td colspan="5" style="text-align:center;padding:7px 12px;color:var(--muted);font-size:0.8rem;">—</td></tr>';
      return;
    }

    algunoDato = true;
    var bruto = parseFloat(raw);
    var bar   = FLV_BAR[v.key][sexo][ne][gi];
    var z     = (bruto - bar.m) / bar.ds;

    var clf, col, badge;
    if (z >= -1.0)      { clf='Normal';     col='var(--green)';  badge='bg-minima'; }
    else if (z >= -1.5) { clf='Leve ↓';     col='var(--yellow)'; badge='bg-leve'; }
    else if (z >= -2.0) { clf='Moderado ↓'; col='var(--orange)'; badge='bg-moderada'; }
    else                { clf='Bajo ↓';     col='var(--red)';    badge='bg-grave'; }

    if (v.tipo === 'Semántica')  zSem.push({label:v.label, z:z});
    if (v.tipo === 'Fonológica') zFon.push({label:v.label, z:z});

    html += '<tr style="border-bottom:1px solid var(--border);">' +
      '<td style="padding:7px 12px;font-size:0.84rem;font-weight:500;">' + v.label + '</td>' +
      '<td style="padding:7px 12px;text-align:center;font-family:\'DM Mono\',monospace;">' + bruto + '</td>' +
      '<td style="padding:7px 12px;text-align:center;font-family:\'DM Mono\',monospace;color:var(--muted);">' + bar.m + '</td>' +
      '<td style="padding:7px 12px;text-align:center;font-family:\'DM Mono\',monospace;color:var(--muted);">' + bar.ds + '</td>' +
      '<td style="padding:7px 12px;text-align:center;font-family:\'DM Mono\',monospace;font-weight:600;color:' + col + ';">' + (z >= 0 ? '+' : '') + z.toFixed(2) + '</td>' +
      '<td style="padding:7px 12px;text-align:center;"><span class="badge ' + badge + '" style="padding:3px 10px;border-radius:20px;font-size:0.72rem;font-weight:700;">' + clf + '</span></td>' +
      '</tr>';
  });

  if (!algunoDato) { alert('Ingresá al menos un puntaje bruto.'); return; }
  document.getElementById('flv-tabla-body').innerHTML = html;

  // Síntesis
  var ps = [];
  var semBajas = zSem.filter(function(x){ return x.z < -1.0; });
  var fonBajas = zFon.filter(function(x){ return x.z < -1.0; });

  if (zSem.length) {
    if (!semBajas.length)
      ps.push('La fluencia verbal semántica se encuentra dentro de los parámetros esperados en todas las categorías evaluadas.');
    else
      ps.push('Se observan dificultades en la fluencia semántica en: ' + semBajas.map(function(x){ return x.label + ' (Z=' + x.z.toFixed(2) + ')'; }).join(', ') + '.');
  }
  if (zFon.length) {
    if (!fonBajas.length)
      ps.push('La fluencia verbal fonológica se encuentra preservada para las letras evaluadas.');
    else
      ps.push('Se observan dificultades en la fluencia fonológica en: ' + fonBajas.map(function(x){ return x.label + ' (Z=' + x.z.toFixed(2) + ')'; }).join(', ') + '.');
  }
  ps.push('<em>Fuente: Marino & Alderete (2010) — Baremos para población adulta argentina (UNC, Córdoba). Esta síntesis es orientativa y debe integrarse con el juicio clínico del profesional.</em>');
  document.getElementById('flv-interp').innerHTML = ps.map(function(p){ return '<p>'+p+'</p>'; }).join('');

  document.getElementById('flv-form').style.display = 'none';
  document.getElementById('flv-resultado').style.display = 'block';
}

function guardarResultadoFLV() {
  if (!SESSION) return;
  var pacId = document.getElementById('flv-paciente').value;
  var fecha = document.getElementById('flv-fecha').value;
  if (!pacId) { toast('Seleccioná un paciente primero'); return; }
  var sexo=document.getElementById('flv-sexo').value;
  var ne=document.getElementById('flv-ne').value;
  var edadI=document.getElementById('flv-edad').value;
  var datosObj={sexo:sexo,ne:ne,edad_grupo:edadI,variables:[]};
  var zAll=[];
  if(sexo&&ne&&edadI!==''){
    var gi=parseInt(edadI);
    FLV_VARS.forEach(function(v){
      var raw=document.getElementById(v.id).value;
      if(raw==='')return;
      var bruto=parseFloat(raw);
      var bar=FLV_BAR[v.key][sexo][ne][gi];
      var z=parseFloat(((bruto-bar.m)/bar.ds).toFixed(2));
      datosObj.variables.push({label:v.label,tipo:v.tipo,bruto:bruto,m:bar.m,ds:bar.ds,z:z});
      zAll.push(z);
    });
  }
  var zPrincipal = zAll.length ? parseFloat((zAll.reduce(function(a,b){return a+b;},0)/zAll.length).toFixed(2)) : null;
  var cat = zAll.length ? (zPrincipal >= -1.0 ? 'Normal' : zPrincipal >= -1.5 ? 'Leve ↓' : zPrincipal >= -2.0 ? 'Moderado ↓' : 'Bajo ↓') : 'Ver detalle';
  var body = { user_id: SESSION.user.id, paciente_id: pacId, test: 'Fluencia Verbal', fecha: fecha,
    puntaje_total: null, categoria: cat,
    puntaje_z: zPrincipal,
    puntaje_t: zPrincipal!==null ? parseFloat((50+10*zPrincipal).toFixed(1)) : null,
    percentil: zPrincipal!==null ? Math.max(1,Math.min(99,Math.round(50+28.57*zPrincipal))) : null,
    datos: datosObj };
  supaFetch('/rest/v1/psico_resultados', 'POST', body, SESSION.access_token)
    .then(function(){
    cargarResultados();
    toast('✓ Resultado guardado', 'success');
    // Animar el botón que estaba activo
    var btnAll = document.querySelectorAll('.vista.active .btn-primary');
    var btn = btnAll.length ? btnAll[btnAll.length-1] : null;
    if(btn){ btn.classList.add('btn-saved'); setTimeout(function(){ btn.classList.remove('btn-saved'); },1500); }
  }).catch(catchGuardarError);
}

// ══ GAD-7 ════════════════════════════════════════════════════════════════════
var GAD_ITEMS = [
  'Sentirse nervioso/a, ansioso/a o con los nervios de punta',
  'No ser capaz de parar o controlar las preocupaciones',
  'Preocuparse demasiado por diferentes cosas',
  'Dificultad para relajarse',
  'Estar tan inquieto/a que resulta difícil permanecer sentado/a',
  'Irritarse o molestarse con facilidad',
  'Sentir miedo, como si algo terrible fuera a ocurrir'
];
function iniciarGAD() {
  var c=document.getElementById('gad-items-container');
  c.innerHTML=GAD_ITEMS.map(function(item,i){
    return '<div class="bdi-item"><div class="bdi-pregunta">'+(i+1)+'. '+item+'</div>' +
      '<div class="bdi-opciones">' +
      PHQ_OPS.map(function(op,j){return '<label class="bdi-opcion"><input type="radio" name="gad_'+i+'" value="'+j+'"><span class="bdi-opcion-texto">'+op+'</span></label>';}).join('') +
      '</div></div>';
  }).join('');
  document.getElementById('gad-fecha').value=new Date().toISOString().split('T')[0];
  document.getElementById('gad-form').style.display='block';
  document.getElementById('gad-resultado').style.display='none';
}
function limpiarGAD(){if(!confirm('¿Limpiar?'))return;document.querySelectorAll('[name^="gad_"]').forEach(function(r){r.checked=false;});}
function calcularGAD() {
  var total=0;var sinR=0;
  for(var i=0;i<7;i++){var s=document.querySelector('[name="gad_'+i+'"]:checked');if(s)total+=parseInt(s.value);else sinR++;}
  if(sinR>0&&!confirm('Hay '+sinR+' ítem(s) sin respuesta. ¿Continuar?'))return;
  var cat,rango,badge,interp;
  if(total<=4)       {cat='Mínima'; rango='0–4';   badge='bg-minima';}
  else if(total<=9)  {cat='Leve';   rango='5–9';   badge='bg-leve';}
  else if(total<=14) {cat='Moderada';rango='10–14';badge='bg-moderada';}
  else               {cat='Grave';  rango='15–21'; badge='bg-grave';}
  var screening=total>=10?'⚠️ Puntaje ≥10: positivo para screening de TAG. Se recomienda evaluación diagnóstica completa.':'Puntaje <10: por debajo del punto de corte para TAG (≥10).';
  if(total<=4) interp='<p>El puntaje ('+total+') indica síntomas de ansiedad <strong>mínimos</strong>.</p>';
  else if(total<=9) interp='<p>El puntaje ('+total+') sugiere <strong>ansiedad leve</strong>. Se recomienda seguimiento.</p>';
  else if(total<=14) interp='<p>El puntaje ('+total+') indica <strong>ansiedad moderada</strong> con impacto funcional. Se sugiere intervención.</p>';
  else interp='<p>El puntaje ('+total+') indica <strong>ansiedad grave</strong>. Se recomienda tratamiento especializado.</p>';
  interp+='<p>'+screening+'</p><p><em>Fuente: Spitzer et al. (2006); García-Campayo et al. (2010). Interpretación orientativa.</em></p>';
  document.getElementById('gad-pts').textContent=total;
  document.getElementById('gad-cat').textContent='Ansiedad '+cat;
  document.getElementById('gad-rango').textContent='Rango: '+rango+' puntos';
  document.getElementById('gad-badge').textContent=cat;
  document.getElementById('gad-badge').className='badge-grande '+badge;
  document.getElementById('gad-interp').innerHTML=interp;
  document.getElementById('gad-form').style.display='none';
  document.getElementById('gad-resultado').style.display='block';
}
function guardarResultadoGAD(){
  if(!SESSION)return;
  var pacId=document.getElementById('gad-paciente').value;
  var pts=parseInt(document.getElementById('gad-pts').textContent);
  var cat=document.getElementById('gad-cat').textContent;
  var fecha=document.getElementById('gad-fecha').value;
  if(!pacId){toast('Seleccioná un paciente primero');return;}
  supaFetch('/rest/v1/psico_resultados','POST',{
    user_id:SESSION.user.id, paciente_id:pacId, test:'GAD-7', fecha:fecha,
    puntaje_total:pts, categoria:cat,
    datos:{ total:pts }
  },SESSION.access_token).then(function(){cargarResultados();
    toast('✓ Resultado guardado', 'success');
    var btnAll = document.querySelectorAll('.vista.active .btn-primary');
    var btn = btnAll.length ? btnAll[btnAll.length-1] : null;
    if(btn){ btn.classList.add('btn-saved'); setTimeout(function(){ btn.classList.remove('btn-saved'); },1500); };}).catch(catchGuardarError);
}



function calcularSCL90Manual() {
  var grupo = document.getElementById('scl90-grupo') ? document.getElementById('scl90-grupo').value || 'adulto' : 'adulto';
  var sexo  = document.getElementById('scl90-sexo')  ? document.getElementById('scl90-sexo').value  || 'F' : 'F';
  var igs   = parseFloat(document.getElementById('man-scl90-igs').value);
  var tsp   = parseFloat(document.getElementById('man-scl90-tsp').value);
  var imsp  = parseFloat(document.getElementById('man-scl90-imsp').value);
  if (isNaN(igs) && isNaN(tsp) && isNaN(imsp)) { toast('Ingresá al menos un valor','error'); return; }
  if (isNaN(igs)) igs = 0; if (isNaN(tsp)) tsp = 0; if (isNaN(imsp)) imsp = 0;
  window._sclIGS = igs; window._sclTSP = tsp; window._sclIMSP = imsp;
  var tIGS = brutoAT_SCL(igs, grupo, sexo, 'IGS');
  var tTSP = brutoAT_SCL(tsp, grupo, sexo, 'TSP');
  var tIMSP= brutoAT_SCL(imsp, grupo, sexo, 'IMSP');
  window._sclTSP_T = tTSP; window._sclIMSP_T = tIMSP;
  function sig(t){ return t>=65?'⚠️ Clínicamente significativo':'Normal'; }
  var tabla = '<table class="scl-t-table"><thead><tr><th>Escala Global</th><th>Bruto</th><th>T</th><th>Estado</th></tr></thead><tbody>'+
    '<tr><td><strong>IGS (Severidad Global)</strong></td><td>'+igs.toFixed(2)+'</td><td>'+tIGS+'</td><td>'+(tIGS>=65?'⚠️ Significativo':'Normal')+'</td></tr>'+
    '<tr><td><strong>TSP (Síntomas Positivos)</strong></td><td>'+tsp+'</td><td>'+tTSP+'</td><td>'+(tTSP>=65?'⚠️ Significativo':'Normal')+'</td></tr>'+
    '<tr><td><strong>IMSP (Malestar Positivo)</strong></td><td>'+imsp.toFixed(2)+'</td><td>'+tIMSP+'</td><td>'+(tIMSP>=65?'⚠️ Significativo':'Normal')+'</td></tr>'+
    '</tbody></table>';
  var interp = (tIGS>=65||tTSP>=65||tIMSP>=65) ?
    '<p>Uno o más índices globales superan el punto de corte clínicamente significativo (T≥65).</p>' :
    '<p>Los índices globales no evidencian niveles clínicamente significativos de malestar general.</p>';
  interp += '<p><em>Carga manual — Baremos: Casullo & Pérez (2008).</em></p>';
  document.getElementById('scl90-detalle').innerHTML = '';
  document.getElementById('scl90-tabla-t').innerHTML = tabla;
  document.getElementById('scl90-interp').innerHTML = interp;
  document.getElementById('scl90-form').style.display = 'none';
  document.getElementById('scl90-resultado').style.display = 'block';
}


// ══ CRC · Cuestionario de Reserva Cognitiva (Rami et al. 2011) ══════════════
var CRC_ITEMS = [
  { id:'esc', label:'Escolaridad', opciones:[
    ['Sin estudios',0],['Lee y escribe (autodidacta)',1],['Básica (< 6 años)',2],
    ['Primaria (≥ 6 años)',3],['Secundaria (≥ 9 años)',4],['Superior (diplomatura/licenciatura)',5]
  ]},
  { id:'esc_pad', label:'Escolaridad de los padres (el de mayor nivel)', opciones:[
    ['No escolarizados',0],['Básica o primaria',1],['Secundaria o superior',2]
  ]},
  { id:'cursos', label:'Cursos de formación', opciones:[
    ['Ninguno',0],['Uno o dos',1],['Entre dos y cinco',2],['Más de cinco',3]
  ]},
  { id:'ocup', label:'Ocupación laboral (a lo largo de la vida)', opciones:[
    ['No cualificado (incluye "sus labores")',0],['Cualificado manual',1],
    ['Cualificado no manual (secretariado, técnico)',2],
    ['Profesional (estudios superiores)',3],['Directivo',4]
  ]},
  { id:'musica', label:'Formación musical', opciones:[
    ['No toca ningún instrumento ni escucha música frecuentemente',0],
    ['Toca poco (aficionado) o escucha música frecuentemente',1],
    ['Formación musical reglada',2]
  ]},
  { id:'idiomas', label:'Idiomas (mantiene una conversación)', opciones:[
    ['Solamente el idioma materno',0],
    ['Dos idiomas (incluye dialectos regionales)',1],
    ['Dos/tres idiomas (uno diferente al idioma materno)',2],
    ['Más de dos idiomas',3]
  ]},
  { id:'lectura', label:'Actividad lectora', opciones:[
    ['Nunca',0],['Ocasionalmente (diario/un libro al año)',1],
    ['Entre dos y cinco libros al año',2],['De 5 a 10 libros al año',3],
    ['Más de 10 libros al año',4]
  ]},
  { id:'juegos', label:'Juegos intelectuales (ajedrez, puzzles, crucigramas)', opciones:[
    ['Nunca o alguna vez',0],['Ocasional (entre 1 y 5 al mes)',1],['Frecuente (más de 5 al mes)',2]
  ]}
];

function crcCatFromTotal(total) {
  if (total <= 6)       return { cat:'Reserva cognitiva baja',       rango:'0–6 (≤C1)',    badge:'bg-grave' };
  if (total <= 9)       return { cat:'Reserva cognitiva media-baja',  rango:'7–9 (C1-C2)',  badge:'bg-moderada' };
  if (total <= 14)      return { cat:'Reserva cognitiva media-alta',  rango:'10–14 (C2-C3)',badge:'bg-leve' };
  return                       { cat:'Reserva cognitiva alta',        rango:'≥15 (≥C4)',    badge:'bg-minima' };
}

function _mostrarResultadoCRC(total) {
  var r = crcCatFromTotal(total);
  var interp = '<p>Puntaje CRC: <strong>'+total+'/25</strong> — '+r.cat+' ('+r.rango+').</p>';
  if (total<=6) interp += '<p>La puntuación sitúa al paciente en el cuartil inferior de reserva cognitiva (≤C1), lo que podría vincularse con mayor vulnerabilidad ante el deterioro.</p>';
  else if (total<=9) interp += '<p>La puntuación corresponde a reserva cognitiva medio-baja (C1-C2). Se sugiere considerar actividades de estimulación cognitiva.</p>';
  else if (total<=14) interp += '<p>La puntuación indica reserva cognitiva medio-alta (C2-C3), compatible con un nivel de protección cognitiva moderado.</p>';
  else interp += '<p>La puntuación sugiere reserva cognitiva alta (≥C4), lo que constituye un factor protector relevante frente al deterioro cognitivo.</p>';
  interp += '<p><em>Rami et al. (2011). Baremos normativos por cuartiles.</em></p>';
  document.getElementById('crc-pts').textContent = total;
  document.getElementById('crc-cat').textContent = r.cat;
  document.getElementById('crc-rango').textContent = 'Rango: '+r.rango;
  document.getElementById('crc-badge').textContent = r.cat;
  document.getElementById('crc-badge').className = 'badge-grande '+r.badge;
  document.getElementById('crc-interp').innerHTML = interp;
  document.getElementById('crc-form').style.display = 'none';
  document.getElementById('crc-resultado').style.display = 'block';
  window._crcTotal = total;
}

function iniciarCRC() {
  var wrap = document.getElementById('crc-items-wrap');
  wrap.innerHTML = CRC_ITEMS.map(function(item, i) {
    var opts = item.opciones.map(function(op) {
      return '<label class="bdi-opcion"><input type="radio" name="crc_'+item.id+'" value="'+op[1]+'"><span class="bdi-opcion-texto">'+op[0]+' ('+op[1]+' pt)</span></label>';
    }).join('');
    return '<div class="bdi-item"><div class="bdi-pregunta">'+(i+1)+'. '+item.label+'</div><div class="bdi-opciones">'+opts+'</div></div>';
  }).join('');
  document.getElementById('crc-fecha').value = new Date().toISOString().split('T')[0];
  document.getElementById('crc-form').style.display = 'block';
  document.getElementById('crc-resultado').style.display = 'none';
}
function limpiarCRC() { if(!confirm('¿Limpiar?'))return; document.querySelectorAll('[name^="crc_"]').forEach(function(r){r.checked=false;}); }
function calcularCRC() {
  var total=0,sinR=0;
  CRC_ITEMS.forEach(function(item) {
    var s=document.querySelector('[name="crc_'+item.id+'"]:checked');
    if(s) total+=parseInt(s.value); else sinR++;
  });
  if(sinR>0&&!confirm('Hay '+sinR+' ítem(s) sin respuesta. ¿Continuar?'))return;
  _mostrarResultadoCRC(total);
}
function calcularCRCManual() {
  var t = parseInt(document.getElementById('man-crc-total').value);
  if(isNaN(t)||t<0||t>25){toast('Ingresá un puntaje entre 0 y 25','error');return;}
  _mostrarResultadoCRC(t);
}
function guardarCRC() {
  if(!SESSION)return;
  var pacId=document.getElementById('crc-paciente').value;
  var fecha=document.getElementById('crc-fecha').value;
  if(!pacId){toast('Seleccioná un paciente primero','error');return;}
  var total=window._crcTotal!=null?window._crcTotal:parseInt(document.getElementById('crc-pts').textContent)||0;
  var cat=document.getElementById('crc-cat').textContent;
  var datos={total:total};
  CRC_ITEMS.forEach(function(item){var s=document.querySelector('[name="crc_'+item.id+'"]:checked');if(s)datos[item.id]=parseInt(s.value);});
  supaFetch('/rest/v1/psico_resultados','POST',{user_id:SESSION.user.id,paciente_id:pacId,test:'CRC',fecha:fecha,puntaje_total:total,categoria:cat,datos:datos},SESSION.access_token)
    .then(function(){cargarResultados();toast('✓ CRC guardado','success');}).catch(catchGuardarError);
}

// ══ PSS-10 · Escala de Estrés Percibido (Cohen et al. 1983) ══════════════════
var PSS_ITEMS = [
  {n:1, text:'¿Con qué frecuencia ha estado afectado/a por algo que ha ocurrido inesperadamente?', inv:false},
  {n:2, text:'¿Con qué frecuencia se ha sentido incapaz de controlar las cosas importantes de su vida?', inv:false},
  {n:3, text:'¿Con qué frecuencia se ha sentido nervioso/a o estresado/a?', inv:false},
  {n:4, text:'¿Con qué frecuencia ha manejado con éxito los pequeños problemas irritantes de la vida?', inv:true},
  {n:5, text:'¿Con qué frecuencia ha sentido que ha afrontado efectivamente los cambios importantes que han estado ocurriendo en su vida?', inv:true},
  {n:6, text:'¿Con qué frecuencia ha estado seguro/a sobre su capacidad para manejar sus problemas personales?', inv:true},
  {n:7, text:'¿Con qué frecuencia ha sentido que las cosas le van bien?', inv:true},
  {n:8, text:'¿Con qué frecuencia ha sentido que no podía afrontar todas las cosas que tenía que hacer?', inv:false},
  {n:9, text:'¿Con qué frecuencia ha podido controlar las dificultades de su vida?', inv:true},
  {n:10,text:'¿Con qué frecuencia ha sentido que tenía todo bajo control?', inv:true}
];
var PSS_OPS = ['Nunca (0)','Casi nunca (1)','A veces (2)','Casi a menudo (3)','Muy a menudo (4)'];

function pssCatFromTotal(total) {
  if(total<=13) return {cat:'Estrés bajo',        rango:'0–13',  badge:'bg-minima'};
  if(total<=26) return {cat:'Estrés moderado',    rango:'14–26', badge:'bg-moderada'};
  return              {cat:'Estrés alto',          rango:'27–40', badge:'bg-grave'};
}
function _mostrarResultadoPSS(total) {
  var r=pssCatFromTotal(total);
  var interp='<p>Puntaje PSS-10: <strong>'+total+'/40</strong> — <strong>'+r.cat+'</strong>.</p>';
  if(total<=13) interp+='<p>El nivel de estrés percibido se encuentra dentro de parámetros esperables.</p>';
  else if(total<=26) interp+='<p>El nivel de estrés percibido es moderado. Se recomienda explorar fuentes de estrés y estrategias de afrontamiento.</p>';
  else interp+='<p>El nivel de estrés percibido es elevado, lo que podría estar afectando el funcionamiento cotidiano. Se sugiere intervención.</p>';
  interp+='<p><em>Cohen, Kamarck & Mermelstein (1983). Ítems 4,5,6,7,9,10 invertidos.</em></p>';
  document.getElementById('pss-pts').textContent=total;
  document.getElementById('pss-cat').textContent=r.cat;
  document.getElementById('pss-rango').textContent='Rango: '+r.rango;
  document.getElementById('pss-badge').textContent=r.cat;
  document.getElementById('pss-badge').className='badge-grande '+r.badge;
  document.getElementById('pss-interp').innerHTML=interp;
  document.getElementById('pss-form').style.display='none';
  document.getElementById('pss-resultado').style.display='block';
  window._pssTotal=total;
}
function iniciarPSS() {
  var wrap=document.getElementById('pss-items-wrap');
  wrap.innerHTML=PSS_ITEMS.map(function(item,i){
    var opts=PSS_OPS.map(function(op,j){return '<label class="bdi-opcion"><input type="radio" name="pss_'+i+'" value="'+j+'"><span class="bdi-opcion-texto">'+op+'</span></label>';}).join('');
    return '<div class="bdi-item"><div class="bdi-pregunta">'+item.n+'. '+item.text+(item.inv?' <span style="font-size:0.75rem;color:var(--muted);">[inverso]</span>':'')+'</div><div class="bdi-opciones">'+opts+'</div></div>';
  }).join('');
  document.getElementById('pss-fecha').value=new Date().toISOString().split('T')[0];
  document.getElementById('pss-form').style.display='block';
  document.getElementById('pss-resultado').style.display='none';
}
function limpiarPSS(){if(!confirm('¿Limpiar?'))return;document.querySelectorAll('[name^="pss_"]').forEach(function(r){r.checked=false;});}
function calcularPSS(){
  var total=0,sinR=0;
  PSS_ITEMS.forEach(function(item,i){
    var s=document.querySelector('[name="pss_'+i+'"]:checked');
    if(s){var v=parseInt(s.value);total+=item.inv?(4-v):v;}else sinR++;
  });
  if(sinR>0&&!confirm('Hay '+sinR+' ítem(s) sin respuesta. ¿Continuar?'))return;
  _mostrarResultadoPSS(total);
}
function calcularPSSManual(){
  var t=parseInt(document.getElementById('man-pss-total').value);
  if(isNaN(t)||t<0||t>40){toast('Ingresá un puntaje entre 0 y 40','error');return;}
  _mostrarResultadoPSS(t);
}
function guardarPSS(){
  if(!SESSION)return;
  var pacId=document.getElementById('pss-paciente').value;
  var fecha=document.getElementById('pss-fecha').value;
  if(!pacId){toast('Seleccioná un paciente primero','error');return;}
  var total=window._pssTotal!=null?window._pssTotal:parseInt(document.getElementById('pss-pts').textContent)||0;
  var cat=document.getElementById('pss-cat').textContent;
  supaFetch('/rest/v1/psico_resultados','POST',{user_id:SESSION.user.id,paciente_id:pacId,test:'PSS-10',fecha:fecha,puntaje_total:total,categoria:cat,datos:{total:total}},SESSION.access_token)
    .then(function(){cargarResultados();toast('✓ PSS-10 guardado','success');}).catch(catchGuardarError);
}

