// ══ EAVA · Escala de Autovaloración de TDAH en Adultos ══════════════════════
// Ítems según cuestionario oficial. Parte A: inatención (1-9) · Parte B: hiper/impulsividad (10-18)
// Etiquetas: 0=Nunca · 1=Raramente · 2=Algunas veces · 3=A menudo · 4=Muy a menudo
// Cortes por subescala: ≥24 muy probable · 17-23 probable · 0-16 baja probabilidad

var EAVA_ITEMS_A = [
  {n:1,  txt:'¿Con qué frecuencia comete errores cuando tiene que trabajar en un proyecto aburrido o difícil?'},
  {n:2,  txt:'¿Con qué frecuencia tiene dificultades para mantener su atención cuando está aburrido o con un trabajo repetitivo?'},
  {n:3,  txt:'¿Con qué frecuencia tiene dificultades para concentrarse en cuestiones que otras personas le comunican, aun cuando se dirijan directamente a usted?'},
  {n:4,  txt:'¿Con qué frecuencia tiene dificultades para concretar los detalles de un proyecto una vez que las partes más difíciles se han conseguido?'},
  {n:5,  txt:'¿Con qué frecuencia tiene dificultades en ordenar las cosas en una tarea que requiere organización?'},
  {n:6,  txt:'Cuando tiene una tarea que requiere mucha reflexión, ¿con qué frecuencia la evita o demora en iniciarla?'},
  {n:7,  txt:'¿Con qué frecuencia extravía cosas o tiene dificultades para encontrarlas en su casa o en el trabajo?'},
  {n:8,  txt:'¿Con qué frecuencia se distrae por actividad o ruido a su alrededor?'},
  {n:9,  txt:'¿Con qué frecuencia tiene dificultades para recordar citas u obligaciones?'}
];

var EAVA_ITEMS_B = [
  {n:10, txt:'¿Con qué frecuencia se inquieta o mueve sus manos o pies cuando tiene que permanecer sentado durante largo tiempo?'},
  {n:11, txt:'¿Con qué frecuencia abandona su asiento en reuniones o en otras situaciones en las cuales debe permanecer sentado?'},
  {n:12, txt:'¿Con qué frecuencia tiene sensación de inquietud?'},
  {n:13, txt:'¿Con qué frecuencia tiene dificultades para relajarse durante el tiempo libre?'},
  {n:14, txt:'¿Con qué frecuencia se nota forzado en realizar actividades, como impulsado por un motor?'},
  {n:15, txt:'¿Con qué frecuencia habla demasiado en ambientes sociales?'},
  {n:16, txt:'Cuando mantiene una conversación, ¿con qué frecuencia permite que los demás terminen sus intervenciones?'},
  {n:17, txt:'¿Con qué frecuencia tiene dificultad para esperar su turno en situaciones que requieran una espera?'},
  {n:18, txt:'¿Con qué frecuencia interrumpe a los demás mientras están ocupados?'}
];

var EAVA_OPS = ['Nunca (0)','Raramente (1)','Algunas veces (2)','A menudo (3)','Muy a menudo (4)'];

function eavaCat(score) {
  if (score >= 24) return { cat:'Muy probable TDAH adulto',  badge:'bg-grave',    lbl:'≥24' };
  if (score >= 17) return { cat:'Probable TDAH adulto',      badge:'bg-moderada', lbl:'17–23' };
  return                  { cat:'Baja probabilidad de TDAH', badge:'bg-minima',   lbl:'0–16' };
}

function _mostrarResultadoEAVA(ptA, ptB) {
  var rA = eavaCat(ptA), rB = eavaCat(ptB);
  var perfilA = ptA >= 17, perfilB = ptB >= 17;
  var perfil = (perfilA && perfilB) ? 'combinado' : perfilA ? 'predominantemente inatento' : perfilB ? 'predominantemente hiperactivo/impulsivo' : null;

  var interp = '<p><strong>Parte A (Inatención):</strong> ' + ptA + '/36 — <strong>' + rA.cat + '</strong> (' + rA.lbl + ').</p>' +
    '<p><strong>Parte B (Hiperactividad/Impulsividad):</strong> ' + ptB + '/36 — <strong>' + rB.cat + '</strong> (' + rB.lbl + ').</p>';

  if (ptA >= 24 || ptB >= 24) {
    interp += '<p>La puntuación es clínicamente significativa, compatible con un perfil <strong>' + perfil + '</strong>. Se recomienda evaluación clínica integral.</p>';
  } else if (ptA >= 17 || ptB >= 17) {
    interp += '<p>La puntuación sugiere síntomas compatibles con TDAH adulto de probabilidad moderada (perfil ' + perfil + '). Puede reflejar un cuadro subclínico o compensado. Justifica evaluación complementaria.</p>';
  } else {
    interp += '<p>La intensidad actual de los síntomas no alcanza umbrales clínicos en ninguna subescala.</p>';
  }
  interp += '<p><em>EAVA — Últimos 6 meses. Corte por subescala: ≥24 muy probable · 17–23 probable · 0–16 baja probabilidad. No es diagnóstica por sí sola. Complementar con ASRS, WURS y entrevista clínica.</em></p>';

  document.getElementById('eava-pts-a').textContent = ptA;
  document.getElementById('eava-cat-a').textContent = rA.cat;
  document.getElementById('eava-badge-a').textContent = rA.cat;
  document.getElementById('eava-badge-a').className = 'badge-grande ' + rA.badge;
  document.getElementById('eava-pts-b').textContent = ptB;
  document.getElementById('eava-cat-b').textContent = rB.cat;
  document.getElementById('eava-badge-b').textContent = rB.cat;
  document.getElementById('eava-badge-b').className = 'badge-grande ' + rB.badge;
  document.getElementById('eava-interp').innerHTML = interp;
  document.getElementById('eava-form').style.display = 'none';
  document.getElementById('eava-resultado').style.display = 'block';
  window._eavaA = ptA; window._eavaB = ptB;
}

function iniciarEAVA() {
  aplicarTituloGlosario('eava-titulo-glosario', 'EAVA', 'EAVA · Escala de Autovaloración de TDAH en Adultos');
  function renderItems(items, containerId) {
    var wrap = document.getElementById(containerId);
    if (!wrap) return;
    wrap.innerHTML = items.map(function(item) {
      var opts = EAVA_OPS.map(function(op, j) {
        return '<label class="bdi-opcion"><input type="radio" name="eava_' + item.n + '" value="' + j + '"><span class="bdi-opcion-texto">' + op + '</span></label>';
      }).join('');
      return '<div class="bdi-item"><div class="bdi-pregunta">' + item.n + '. ' + item.txt + '</div><div class="bdi-opciones">' + opts + '</div></div>';
    }).join('');
  }
  renderItems(EAVA_ITEMS_A, 'eava-items-a');
  renderItems(EAVA_ITEMS_B, 'eava-items-b');
  document.getElementById('eava-fecha').value = new Date().toISOString().split('T')[0];
  document.getElementById('eava-form').style.display = 'block';
  document.getElementById('eava-resultado').style.display = 'none';
}

function limpiarEAVA() {
  if (!confirm('¿Limpiar todos los ítems?')) return;
  for (var i = 1; i <= 18; i++) {
    document.querySelectorAll('input[name="eava_' + i + '"]').forEach(function(r){ r.checked = false; });
  }
}

function calcularEAVA() {
  var ptA = 0, ptB = 0, sinR = 0;
  EAVA_ITEMS_A.forEach(function(item) {
    var s = document.querySelector('input[name="eava_' + item.n + '"]:checked');
    if (s) ptA += parseInt(s.value); else sinR++;
  });
  EAVA_ITEMS_B.forEach(function(item) {
    var s = document.querySelector('input[name="eava_' + item.n + '"]:checked');
    if (s) ptB += parseInt(s.value); else sinR++;
  });
  if (sinR > 0 && !confirm('Hay ' + sinR + ' ítem(s) sin respuesta. ¿Continuar?')) return;
  _mostrarResultadoEAVA(ptA, ptB);
}

function calcularEAVAManual() {
  var a = parseInt(document.getElementById('man-eava-a').value);
  var b = parseInt(document.getElementById('man-eava-b').value);
  if (isNaN(a) || isNaN(b) || a < 0 || a > 36 || b < 0 || b > 36) {
    toast('Ingresá puntajes válidos (0–36 para cada parte)', 'error'); return;
  }
  _mostrarResultadoEAVA(a, b);
}

function guardarEAVA() {
  if (!SESSION) return;
  var pacId = document.getElementById('eava-paciente').value;
  var fecha = document.getElementById('eava-fecha').value;
  if (!pacId) { toast('Seleccioná un paciente primero', 'error'); return; }
  var ptA = window._eavaA != null ? window._eavaA : 0;
  var ptB = window._eavaB != null ? window._eavaB : 0;
  var rA = eavaCat(ptA), rB = eavaCat(ptB);
  var catGlobal = (ptA >= 24 || ptB >= 24) ? 'Muy probable TDAH adulto' : (ptA >= 17 || ptB >= 17) ? 'Probable TDAH adulto' : 'Baja probabilidad';
  supaFetch('/rest/v1/psico_resultados', 'POST', {
    user_id: SESSION.user.id, paciente_id: pacId, test: 'EAVA', fecha: fecha,
    puntaje_total: ptA + ptB, categoria: catGlobal,
    datos: { parte_a: ptA, parte_b: ptB, cat_a: rA.cat, cat_b: rB.cat }
  }, SESSION.access_token).then(function() {
    cargarResultados(); toast('✓ EAVA guardado', 'success');
    var btn = document.querySelector('.vista.active .btn-primary:last-child');
    if (btn) { btn.classList.add('btn-saved'); setTimeout(function(){ btn.classList.remove('btn-saved'); }, 1500); }
  }).catch(catchGuardarError);
}

