function aqInterp(total) {
  if (total <= 10) return { cat:'Bajo', fenotipo:'—', txt:'Baja presencia de rasgos autistas. Perfil típico sin indicios relevantes de características del espectro.', badge:'bg-minima' };
  if (total <= 22) return { cat:'Medio', fenotipo:'Población general', txt:'Puntuación dentro del rango esperado (media femenina ≈15; masculina ≈17). No se identifican rasgos clínicamente significativos.', badge:'bg-minima' };
  if (total <= 28) return { cat:'Sobre la media', fenotipo:'BAP', txt:'Fenotipo ampliado del autismo (BAP): rasgos leves compatibles con el espectro que no interfieren significativamente. Frecuente en familiares de personas con TEA.', badge:'bg-moderada' };
  if (total <= 34) return { cat:'Sobre la media', fenotipo:'MAP', txt:'Fenotipo medio del autismo (MAP): rasgos más notorios por debajo del umbral diagnóstico. Pueden impactar moderadamente en lo social/comunicativo.', badge:'bg-moderada' };
  return { cat:'Muy alto', fenotipo:'NAP', txt:'Fenotipo reducido del autismo (NAP): alta expresión de rasgos autistas, compatible con TEA de alto funcionamiento o Asperger (media ≈35). Sugiere evaluación diagnóstica específica.', badge:'bg-grave' };
}

function eqInterp(total) {
  if (total <= 32) return { cat:'Bajo', txt:'Nivel significativamente bajo de empatía cognitiva y afectiva. Puede asociarse con dificultades para percibir e interpretar estados mentales ajenos (media TEA/Asperger ≈20).', badge:'bg-grave' };
  if (total <= 52) return { cat:'Medio', txt:'Empatía dentro del rango normativo (media femenina 47; masculina 42). Habilidades empáticas funcionales para la interacción social cotidiana.', badge:'bg-minima' };
  if (total <= 63) return { cat:'Sobre la media', txt:'Nivel elevado de empatía. Marcada sensibilidad hacia las emociones ajenas y buena capacidad de respuesta emocional.', badge:'bg-leve' };
  return { cat:'Muy alto', txt:'Nivel excepcionalmente alto de empatía. Fuerte tendencia prosocial; en algunos casos puede conllevar vulnerabilidad emocional.', badge:'bg-leve' };
}

function ndShowResult(formId, resId, fn) { document.getElementById(formId).style.display='none'; document.getElementById(resId).style.display='block'; if(fn) fn(); }

function ndInitTest(prefix, fechaId, formId, resId, renderFn) {
  var f = document.getElementById(fechaId); if (f) f.value = new Date().toISOString().split('T')[0];
  document.getElementById(formId).style.display = 'block';
  document.getElementById(resId).style.display = 'none';
  if (renderFn) renderFn();
}

function ndGuardar(testName, pacSelId, fechaId, total, cat, datos) {
  if (!SESSION) return;
  var pacId = document.getElementById(pacSelId).value;
  var fecha = document.getElementById(fechaId).value;
  if (!pacId) { toast('Seleccioná un paciente.', 'error'); return; }
  return supaFetch('/rest/v1/psico_resultados', 'POST', {
    user_id: SESSION.user.id, paciente_id: pacId, test: testName, fecha: fecha,
    puntaje_total: total, categoria: cat, datos: datos
  }, SESSION.access_token).then(function() {
    cargarResultados(); toast('✓ ' + testName + ' guardado', 'success');
  }).catch(catchGuardarError);
}

