function aqScoreFromResponses(getVal) {
  var total = 0;
  for (var i = 1; i <= 50; i++) {
    var v = getVal(i); if (v == null) continue;
    if (AQ_AGREE.indexOf(i) >= 0 && v <= 2) total++;
    else if (AQ_DISAGREE.indexOf(i) >= 0 && v >= 3) total++;
  }
  return total;
}

function _mostrarAQ(total) {
  var r = aqInterp(total);
  document.getElementById('aq-pts').textContent = total;
  document.getElementById('aq-cat').textContent = r.cat + (r.fenotipo !== '—' ? ' · ' + r.fenotipo : '');
  document.getElementById('aq-badge').textContent = r.cat;
  document.getElementById('aq-badge').className = 'badge-grande ' + r.badge;
  document.getElementById('aq-interp').innerHTML = '<p><strong>Puntaje AQ: ' + total + '/50 — ' + r.cat + '</strong>' + (r.fenotipo !== '—' ? ' (' + r.fenotipo + ')' : '') + '.</p><p>' + r.txt + '</p><p><em>Baron-Cohen et al. · Síntesis orientativa — integrar con entrevista clínica y evaluación neuropsicológica.</em></p>';
  window._aqData = { total: total, cat: r.cat, fenotipo: r.fenotipo };
  ndShowResult('aq-form', 'aq-resultado');
}

function iniciarAQ() { ndInitTest('aq','aq-fecha','aq-form','aq-resultado', function(){ ndRenderLikert4('aq', AQ_ITEMS, ND_LIKERT4_AQ, 'aq-items'); }); }
function limpiarAQ() { for (var i=1;i<=50;i++) document.querySelectorAll('input[name="aq_'+i+'"]').forEach(function(r){r.checked=false;}); }
function calcularAQ() {
  var sin = 0, total = aqScoreFromResponses(function(n){ var s=document.querySelector('input[name="aq_'+n+'"]:checked'); if(!s){sin++;return null;} return parseInt(s.value,10); });
  if (sin && !confirm('Hay '+sin+' ítem(s) sin respuesta. ¿Continuar?')) return;
  _mostrarAQ(total);
}
function calcularAQManual() { var t=parseInt(document.getElementById('man-aq-total').value,10); if(isNaN(t)||t<0||t>50){toast('Puntaje 0–50','error');return;} _mostrarAQ(t); }
function guardarAQ() { if(!window._aqData){toast('Calculá antes de guardar','error');return;} ndGuardar('AQ','aq-paciente','aq-fecha',window._aqData.total,window._aqData.cat,window._aqData); }

