function eqScoreFromResponses(getVal) {
  var total = 0;
  for (var i = 1; i <= 60; i++) {
    var v = getVal(i); if (v == null) continue;
    if (EQ_AGREE.indexOf(i) >= 0) { if (v === 1) total += 2; else if (v === 2) total += 1; }
    else if (EQ_DISAGREE.indexOf(i) >= 0) { if (v === 4) total += 2; else if (v === 3) total += 1; }
  }
  return total;
}

