function dislexAnimarGuardar() {
  var btnAll = document.querySelectorAll('.vista.active .btn-primary');
  var btn = btnAll.length ? btnAll[btnAll.length - 1] : null;
  if (btn) { btn.classList.add('btn-saved'); setTimeout(function() { btn.classList.remove('btn-saved'); }, 1500); }
}

function ndRenderDislex2Items() {
  var wrap = document.getElementById('dislex2-items');
  if (!wrap) return;
  wrap.innerHTML = DISLEX2_ITEMS.map(function(item) {
    var star = item.imp ? ' <span style="font-size:0.7rem;font-weight:700;color:#c0392b;">*</span>' : '';
    return '<div class="bdi-item"><div class="bdi-pregunta">' + item.n + '. ' + item.txt + star + '</div>' +
      '<div class="bdi-opciones">' +
      '<label class="bdi-opcion"><input type="radio" name="dislex2_' + item.n + '" value="si" onchange="dislex2Update()"><span class="bdi-opcion-texto">Sí</span></label>' +
      '<label class="bdi-opcion"><input type="radio" name="dislex2_' + item.n + '" value="no" onchange="dislex2Update()"><span class="bdi-opcion-texto">No</span></label>' +
      '</div></div>';
  }).join('');
  dislex2Update();
}

