  aplicarTituloGlosario('dislex1-titulo-glosario', 'Cuest. Dislexia Adultos', 'Breve Cuestionario para Valorar Dislexia en Adultos');
  ndInitTest('dislex1', 'dislex1-fecha', 'dislex1-form', 'dislex1-resultado', function() {
    ndRenderDislex1Items();
    setModo('dislex1', 'auto');
  });
