function dislex1Update() {
  var checked = document.querySelectorAll('input[name="dislex1_item"]:checked').length;
  var cat = checked >= 5 ? 'Significativo' : 'No significativo';
  document.getElementById('dislex1-live').textContent = checked + ' / 10';
  document.getElementById('dislex1-live-cat').textContent = checked > 0 ? '— ' + cat : '';
}

function limpiarDislex1() {
  if (!confirm('¿Limpiar?')) return;
  document.querySelectorAll('input[name="dislex1_item"]').forEach(function(cb){ cb.checked = false; });
  document.getElementById('dislex1-obs').value = '';
  dislex1Update();
}

function dislexMostrarResultado1(total, cat, marcados, obs) {
  var badge = total >= 5 ? 'bg-grave' : 'bg-minima';
  var interp = '<p>Puntaje: <strong>' + total + '/10</strong> — <strong>' + cat + '</strong>.</p>';
  if (total >= 5) interp += '<p>La cantidad de indicadores marcados sugiere características compatibles con dislexia. Se recomienda evaluación complementaria.</p>';
  else interp += '<p>La cantidad de indicadores marcados no alcanza el umbral sugestivo de dislexia.</p>';
  if (marcados.length) interp += '<p>Ítems marcados: ' + marcados.join(', ') + '.</p>';
  if (obs) interp += '<p><em>Observaciones: ' + obs + '</em></p>';
  document.getElementById('dislex1-pts').textContent = total;
  document.getElementById('dislex1-cat').textContent = cat;
  document.getElementById('dislex1-badge').textContent = cat;
  document.getElementById('dislex1-badge').className = 'badge-grande ' + badge;
  document.getElementById('dislex1-interp').innerHTML = interp;
  window._dislex1 = { total: total, cat: cat, marcados: marcados, obs: obs };
  ndShowResult('dislex1-form', 'dislex1-resultado');
}

function calcularDislex1Manual() {
  var t = parseInt(document.getElementById('man-dislex1-total').value, 10);
  if (isNaN(t) || t < 0 || t > 10) { toast('Puntaje entre 0 y 10', 'error'); return; }
  var cat = t >= 5 ? 'Significativo' : 'No significativo';
  dislexMostrarResultado1(t, cat, [], document.getElementById('dislex1-obs').value.trim());
}

function calcularDislex1() {
  var marcados = [];
  document.querySelectorAll('input[name="dislex1_item"]:checked').forEach(function(cb) { marcados.push(parseInt(cb.value, 10)); });
  var total = marcados.length;
  var cat = total >= 5 ? 'Significativo' : 'No significativo';
  var obs = document.getElementById('dislex1-obs').value.trim();
  dislexMostrarResultado1(total, cat, marcados, obs);
}

function guardarDislex1() {
  if (!SESSION) return;
  if (!window._dislex1) { toast('Calculá el resultado antes de guardar', 'error'); return; }
  var pacId = document.getElementById('dislex1-paciente').value;
  var fecha = document.getElementById('dislex1-fecha').value;
  if (!pacId) { toast('Seleccioná un paciente', 'error'); return; }
  var d = window._dislex1;
  supaFetch('/rest/v1/psico_resultados', 'POST', {
    user_id: SESSION.user.id, paciente_id: pacId,
    test: 'Cuest. Dislexia Adultos', fecha: fecha,
    puntaje_total: d.total, categoria: d.cat,
    datos: { puntaje_sobre: 10, items_marcados: d.marcados, observaciones: d.obs }
  }, SESSION.access_token).then(function() {
    cargarResultados(); toast('✓ Resultado guardado', 'success');
    dislexAnimarGuardar();
  }).catch(catchGuardarError);
}

