  adulto_M:{SOM:{M:0.40,DS:0.50},OBS:{M:0.72,DS:0.65},SI:{M:0.46,DS:0.52},DEP:{M:0.55,DS:0.57},ANS:{M:0.37,DS:0.47},HOS:{M:0.30,DS:0.42},FOB:{M:0.14,DS:0.32},PAR:{M:0.40,DS:0.49},PSI:{M:0.24,DS:0.38},IGS:{M:0.41,DS:0.44},TSP:{M:24.8,DS:19.2},IMSP:{M:1.32,DS:0.65}},
