    DEP:[0.05,0.23,0.38,0.62,0.85,1.23,1.77,2,2.23,2.8,3.31,3.69],
    ANS:[0,0.2,0.3,0.6,0.8,1.2,1.6,1.8,2.13,2.5,3.04,3.1],
    HOS:[0,0,0.17,0.33,0.67,1,1.5,1.67,1.83,2.56,3.17,3.33],
