/** Convierte logo (JPEG/PNG) a PNG válido para Word — misma lógica que _ref_docx */
function _prepareLogoPngBytes(logoB64OrDataUrl) {
  return new Promise(function(resolve) {
    try {
      var b64 = logoB64OrDataUrl;
      if (String(b64).indexOf('data:') === 0) {
        var parsed = parseDataUrl(b64);
        b64 = parsed ? parsed.b64 : b64;
      }
      var bin = atob(b64), raw = new Uint8Array(bin.length);
      for (var i = 0; i < bin.length; i++) raw[i] = bin.charCodeAt(i);
      var mime = (raw[0] === 0x89 && raw[1] === 0x50) ? 'image/png' : 'image/jpeg';
      var done = function(bytes) { resolve(bytes); };
      if (typeof createImageBitmap === 'function') {
        createImageBitmap(new Blob([raw], { type: mime })).then(function(bmp) {
          var c = document.createElement('canvas');
          c.width = bmp.width;
          c.height = bmp.height;
          var ctx = c.getContext('2d');
          ctx.drawImage(bmp, 0, 0);
          c = _trimLogoCanvas(c);
          c.toBlob(function(blob) {
            if (!blob) { done(raw); return; }
            blob.arrayBuffer().then(function(buf) { done(new Uint8Array(buf)); });
          }, 'image/png');
        }).catch(function() { done(raw); });
      } else {
        var img = new Image();
        img.onload = function() {
          var c = document.createElement('canvas');
          c.width = img.naturalWidth;
          c.height = img.naturalHeight;
          c.getContext('2d').drawImage(img, 0, 0);
          c = _trimLogoCanvas(c);
          var dataUrl = c.toDataURL('image/png');
          var p = parseDataUrl(dataUrl);
          if (p) {
            var b = atob(p.b64), arr = new Uint8Array(b.length);
            for (var j = 0; j < b.length; j++) arr[j] = b.charCodeAt(j);
            done(arr);
          } else { done(raw); }
        };
        img.onerror = function() { done(raw); };
        img.src = 'data:' + mime + ';base64,' + b64;
      }
    } catch (e) { resolve(null); }
  });
}

// A4 vertical, márgenes 720: ancho útil ~10260 DXA (~18 cm)
var WORD_CONTENT_W = 10260;
var WORD_SZ_BUMP = 3; // +1,5 pt global (sz en half-points)
function _wordSz(n) { return n + WORD_SZ_BUMP; }
var WORD_LOGO_COL_W = 3200;
function _wordScaleCols(base, total) {
  var sum = base.reduce(function(a, b) { return a + b; }, 0);
  var out = base.map(function(w) { return Math.round(w * total / sum); });
  out[out.length - 1] += total - out.reduce(function(a, b) { return a + b; }, 0);
  return out;
}

function buildWordHeaderXml(hasGp, hasCt, gpSize, ctSize) {
  gpSize = gpSize || _logoFitEmu(null);
  ctSize = ctSize || _logoFitEmu(null);
  var hdrNs = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
    '<w:hdr xmlns:wpc="http://schemas.microsoft.com/office/word/2010/wordprocessingCanvas"' +
    ' xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006"' +
    ' xmlns:o="urn:schemas-microsoft-com:office:office"' +
    ' xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"' +
    ' xmlns:m="http://schemas.openxmlformats.org/officeDocument/2006/math"' +
    ' xmlns:v="urn:schemas-microsoft-com:vml"' +
    ' xmlns:wp14="http://schemas.microsoft.com/office/word/2010/wordprocessingDrawing"' +
    ' xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing"' +
    ' xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"' +
    ' xmlns:w14="http://schemas.microsoft.com/office/word/2010/wordml"' +
    ' xmlns:wpg="http://schemas.microsoft.com/office/word/2010/wordprocessingGroup"' +
    ' xmlns:wpi="http://schemas.microsoft.com/office/word/2010/wordprocessingInk"' +
    ' xmlns:wne="http://schemas.microsoft.com/office/word/2006/wordml"' +
    ' xmlns:wps="http://schemas.microsoft.com/office/word/2010/wordprocessingShape"' +
    ' mc:Ignorable="w14 wp14">';
  var sep = '<w:p><w:pPr><w:spacing w:before="60" w:after="0"/>' +
    '<w:pBdr><w:bottom w:val="single" w:sz="6" w:space="1" w:color="3a8f8f"/></w:pBdr></w:pPr></w:p>';
  var logoCol = WORD_LOGO_COL_W;
  var centerCol = WORD_CONTENT_W - logoCol * 2;
  if (hasGp || hasCt) {
    var gpCell = hasGp
      ? '<w:p><w:pPr><w:jc w:val="left"/><w:spacing w:before="0" w:after="0"/></w:pPr><w:r><w:rPr/>' + wordLogoDrawing('rImgGP', gpSize.cx, gpSize.cy, 1, 'LogoGP', 'Logo González Palau') + '</w:r></w:p>'
      : '<w:p><w:pPr><w:spacing w:before="0" w:after="0"/></w:pPr></w:p>';
    var ctCell = hasCt
      ? '<w:p><w:pPr><w:jc w:val="right"/><w:spacing w:before="0" w:after="0"/></w:pPr><w:r><w:rPr/>' + wordLogoDrawing('rImgCT', ctSize.cx, ctSize.cy, 2, 'LogoCT', 'Logo CIATEC') + '</w:r></w:p>'
      : '<w:p><w:pPr><w:spacing w:before="0" w:after="0"/></w:pPr></w:p>';
    return hdrNs +
      '<w:tbl><w:tblPr><w:tblW w:w="'+WORD_CONTENT_W+'" w:type="dxa"/><w:tblBorders>' +
      '<w:top w:val="none"/><w:left w:val="none"/><w:bottom w:val="none"/><w:right w:val="none"/>' +
      '<w:insideH w:val="none"/><w:insideV w:val="none"/></w:tblBorders><w:tblLayout w:type="fixed"/></w:tblPr>' +
      '<w:tblGrid><w:gridCol w:w="'+logoCol+'"/><w:gridCol w:w="'+centerCol+'"/><w:gridCol w:w="'+logoCol+'"/></w:tblGrid>' +
      '<w:tr><w:tc><w:tcPr><w:tcW w:w="'+logoCol+'" w:type="dxa"/></w:tcPr>' + gpCell + '</w:tc>' +
      '<w:tc><w:tcPr><w:tcW w:w="'+centerCol+'" w:type="dxa"/></w:tcPr><w:p><w:pPr><w:spacing w:before="0" w:after="0"/></w:pPr></w:p></w:tc>' +
      '<w:tc><w:tcPr><w:tcW w:w="'+logoCol+'" w:type="dxa"/></w:tcPr>' + ctCell + '</w:tc></w:tr></w:tbl>' + sep + '</w:hdr>';
  }
  return hdrNs +
    '<w:tbl><w:tblPr><w:tblW w:w="'+WORD_CONTENT_W+'" w:type="dxa"/><w:tblBorders>' +
    '<w:top w:val="none"/><w:left w:val="none"/><w:bottom w:val="none"/><w:right w:val="none"/>' +
    '<w:insideH w:val="none"/><w:insideV w:val="none"/></w:tblBorders></w:tblPr>' +
    '<w:tr><w:tc><w:tcPr><w:tcW w:w="'+WORD_CONTENT_W+'" w:type="dxa"/></w:tcPr>' +
    '<w:p><w:pPr><w:jc w:val="center"/><w:spacing w:before="0" w:after="0"/></w:pPr>' +
    '<w:r><w:rPr><w:b/><w:sz w:val="'+_wordSz(18)+'"/><w:szCs w:val="'+_wordSz(18)+'"/><w:color w:val="2a6e6e"/>' +
    '<w:rFonts w:ascii="Arial" w:hAnsi="Arial"/></w:rPr>' +
    '<w:t>CENTRO DE REHABILITACIÓN GONZÁLEZ PALAU — FUNDACIÓN CIATEC</w:t></w:r></w:p>' +
    '</w:tc></w:tr></w:tbl>' + sep + '</w:hdr>';
}

// â”€â”€ Firmas de profesionales (4 slots fijos, precargadas) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
var FIRMA_PROFESIONALES = [
  { id: 'JULI',   nombre: 'JULI',   src: 'data:image/png;base64,' },
  { id: 'DANIEL', nombre: 'DANIEL', src: 'data:image/png;base64,' },
  { id: 'ERWIN',  nombre: 'ERWIN',  src: 'data:image/png;base64,' },
  { id: 'FATIMA', nombre: 'FÁTIMA', src: 'data:image/png;base64,' }
];
var FIRMA_SEL_LS_KEY = 'igp_firmas_seleccionadas';
var WORD_FIRMA_EMU_W = 1600000;
var WORD_FIRMA_EMU_H = 900000;
var _firmaDataUrlCache = {};

function getFirmaProfesional(id) {
  var p = FIRMA_PROFESIONALES.find(function(x) { return x.id === id; });
  return p ? p.src : null;
}

function loadFirmaDataUrl(prof) {
  if (_firmaDataUrlCache[prof.id]) return Promise.resolve(_firmaDataUrlCache[prof.id]);
  var src = getFirmaProfesional(prof.id);
  if (!src) return Promise.reject(new Error('firma'));
  _firmaDataUrlCache[prof.id] = src;
  return Promise.resolve(src);
}

function getFirmasSeleccionadasLS() {
  try {
    var raw = localStorage.getItem(FIRMA_SEL_LS_KEY);
    if (!raw) return null;
    return JSON.parse(raw);
  } catch (e) { return null; }
}

function saveFirmasSeleccionadasLS(sel) {
  try { localStorage.setItem(FIRMA_SEL_LS_KEY, JSON.stringify(sel || {})); } catch (e) {}
}

function getFirmasParaInforme(inf) {
  var cfg = infExtraerConfig(inf || {}).cfg;
  var sel = Object.assign({}, infDefaultCfg().firmas_seleccionadas, cfg.firmas_seleccionadas || {});
  var ls = getFirmasSeleccionadasLS();
  if (ls) {
    FIRMA_PROFESIONALES.forEach(function(p) {
      if (ls[p.id] !== undefined) sel[p.id] = !!ls[p.id];
    });
  }
  return FIRMA_PROFESIONALES.filter(function(p) { return sel[p.id]; }).map(function(p) {
    var img = getFirmaProfesional(p.id);
    return { id: p.id, nombre: p.nombre, src: img, img: img };
  });
}

function initFirmasUI(selOverride) {
  var wrap = document.getElementById('inf-firmas-slots');
  if (!wrap) return;
  var sel = Object.assign({}, infDefaultCfg().firmas_seleccionadas);
  var ls = getFirmasSeleccionadasLS();
  if (ls) Object.assign(sel, ls);
  if (selOverride) Object.assign(sel, selOverride);
  wrap.innerHTML = FIRMA_PROFESIONALES.map(function(p) {
    var img = getFirmaProfesional(p.id);
    return '<div style="display:grid;grid-template-columns:28px 90px 1fr;align-items:center;gap:12px;padding:8px 10px;background:var(--surface2);border-radius:8px;border:1px solid var(--border);">' +
      '<input type="checkbox" id="inf-firma-chk-' + p.id + '" ' + (sel[p.id] ? 'checked' : '') + ' onchange="firmaProfesionalToggle(\'' + p.id + '\')" style="accent-color:var(--accent);width:16px;height:16px;">' +
      '<span style="font-size:0.85rem;font-weight:700;">' + p.nombre + '</span>' +
      '<img src="' + img + '" alt="Firma ' + p.nombre + '" style="max-width:150px;max-height:60px;object-fit:contain;background:#fff;border-radius:4px;border:1px solid var(--border);padding:3px;">' +
    '</div>';
  }).join('');
}

function firmaProfesionalToggle(id) {
  var cfg = infGetConfigFromForm();
  saveFirmasSeleccionadasLS(cfg.firmas_seleccionadas);
}

function preloadFirmasIntegradas() {
  FIRMA_PROFESIONALES.forEach(function(p) { loadFirmaDataUrl(p).catch(function() {}); });
}

function buildFirmasPdfHtml(firmas) {
  if (!firmas || !firmas.length) return '';
  function slot(f) {
    var src = f.img || f.src;
    return '<div style="flex:0 0 200px;text-align:center;">' +
      '<img src="' + src + '" style="max-height:90px;max-width:180px;display:block;margin:0 auto;object-fit:contain;">' +
    '</div>';
  }
  if (firmas.length === 1) {
    return '<div style="margin-top:50px;display:flex;justify-content:center;">' + slot(firmas[0]) + '</div>';
  }
  var html = '<div style="margin-top:50px;">';
  for (var i = 0; i < firmas.length; i += 2) {
    var row = firmas.slice(i, i + 2);
    var justify = row.length === 1 ? 'center' : 'space-around';
    html += '<div style="display:flex;justify-content:' + justify + ';gap:40px;margin-bottom:28px;max-width:540px;margin-left:auto;margin-right:auto;">';
    row.forEach(function(f) { html += slot(f); });
    html += '</div>';
  }
  return html + '</div>';
}

function _wFirmaProfCell(f, cellW, span) {
  var inner = '<w:p><w:pPr><w:jc w:val="center"/><w:spacing w:before="0" w:after="40"/></w:pPr>' +
    '<w:r><w:rPr/>' + wordLogoDrawing(f.relId, WORD_FIRMA_EMU_W, WORD_FIRMA_EMU_H, f.docPrId, 'Firma' + f.prof.id, f.prof.nombre) + '</w:r></w:p>';
  var opts = {w: cellW, fill: 'FFFFFF'};
  if (span) opts.span = span;
  return _wCell(inner, opts);
}

function buildFirmasWordSection(firmasList) {
  firmasList = firmasList || [];
  if (!firmasList.length) return { xml: '', rels: [], media: [] };
  var colW = Math.floor(WORD_CONTENT_W / 2);
  var media = [], rels = [], startImgNum = 3;
  firmasList.forEach(function(f, i) {
    f.relId = 'rFirma' + (i + 1);
    f.mediaName = 'image' + (startImgNum + i) + '.png';
    f.docPrId = 100 + i;
    media.push({name: 'word/media/' + f.mediaName, data: f.pngBytes});
    rels.push('<Relationship Id="' + f.relId + '" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/' + f.mediaName + '"/>');
  });
  var tblBorders = '<w:tblBorders><w:top w:val="none"/><w:left w:val="none"/><w:bottom w:val="none"/><w:right w:val="none"/>' +
    '<w:insideH w:val="none"/><w:insideV w:val="none"/></w:tblBorders>';
  var tblPr = '<w:tblPr><w:tblW w:w="' + WORD_CONTENT_W + '" w:type="dxa"/><w:tblLayout w:type="fixed"/>' + tblBorders + '</w:tblPr>';
  var xml = _wPar('', {before: 400, after: 0});
  if (firmasList.length === 1) {
    xml += '<w:tbl>' + tblPr + '<w:tblGrid><w:gridCol w:w="' + WORD_CONTENT_W + '"/></w:tblGrid>' +
      _wRow([_wFirmaProfCell(firmasList[0], WORD_CONTENT_W)]) + '</w:tbl>';
  } else {
    xml += '<w:tbl>' + tblPr + '<w:tblGrid><w:gridCol w:w="' + colW + '"/><w:gridCol w:w="' + colW + '"/></w:tblGrid>';
    for (var i = 0; i < firmasList.length; i += 2) {
      var row = firmasList.slice(i, i + 2);
      if (row.length === 2) {
        xml += _wRow([_wFirmaProfCell(row[0], colW), _wFirmaProfCell(row[1], colW)]);
      } else {
        xml += _wRow([_wFirmaProfCell(row[0], WORD_CONTENT_W, 2)]);
      }
    }
    xml += '</w:tbl>';
  }
  return { xml: xml, rels: rels, media: media };
}


