// ── Helpers ──
function dolorGV(id) { var e=document.getElementById(id); return (e&&e.value!=='') ? parseFloat(e.value) : null; }
// Lee un radio button por nombre (para PCS, CSQ, PBQ) o hidden input (para BPI)
function dolorGVR(prefix, num) {
  var s = document.querySelector('[name="'+prefix+num+'"]:checked');
  return s ? parseInt(s.value) : null;
}
// Para BPI — lee hidden input sincronizado desde radio
function bpiGV(id) {
  var s = document.querySelector('[name="bpi_'+id+'"]:checked');
  return s ? parseFloat(s.value) : null;
}
function dolorZC(v,m,s) { return s>0 ? (v-m)/s : 0; }
function dolorToPc(score, col, table) {
  var pc=1;
  for(var i=0;i<table.length;i++){
    if(table[i][col+1]===null) continue;
    if(score>=table[i][col+1]) pc=table[i][0]; else break;
  }
  return pc;
}
function dolorColorNiv(pc) {
  if(pc>=90) return {txt:'Muy elevado', c:'#c0392b'};
  if(pc>=75) return {txt:'Elevado', c:'#D85A30'};
  if(pc>=40) return {txt:'Moderado', c:'#BA7517'};
  return {txt:'Bajo', c:'#639922'};
}
function dolorColorBPI(v, tipo) {
  if(tipo==='int') {
    if(v>=7) return {txt:'Severa', c:'#c0392b'};
    if(v>=4) return {txt:'Moderada', c:'#D85A30'};
    if(v>=1) return {txt:'Leve', c:'#BA7517'};
    return {txt:'Sin dolor', c:'#639922'};
  }
  if(v>=7) return {txt:'Severa', c:'#c0392b'};
  if(v>=4) return {txt:'Moderada', c:'#D85A30'};
  if(v>=1) return {txt:'Leve', c:'#BA7517'};
  return {txt:'Sin interferencia', c:'#639922'};
}

