// VERSIÓN ORAL: Vanotti et al. (2015) — Buenos Aires — n=297
// M y DS por grupo: edad [0=19-35, 1=36-50, 2=51-70] × escol [0=3-11, 1=12-16, 2=>16]
var SDMT_ORAL = {
  M: [
    [45.31, 56.43, 56.29],  // 19-35
    [44.22, 49.92, 54.88],  // 36-50
    [39.10, 44.93, 50.63]   // 51-70
  ],
  DS: [
    [11.49, 11.50, 12.06],
    [9.64,  12.51, 12.62],
    [10.13, 10.83, 9.47]
  ]
};

function sdmtBuscarPc(tabla, ei, gi, score) {
  var row = tabla[ei][gi];
  var pc = 1;
  for (var i = 0; i < SDMT_PC_LABELS.length; i++) {
    if (score >= row[i]) pc = SDMT_PC_LABELS[i];
    else break;
  }
  return pc;
}

function sdmtPcToZ(pc) {
  var t={1:-2.33,2:-2.05,3:-1.88,4:-1.75,5:-1.64,6:-1.55,7:-1.48,8:-1.41,9:-1.34,
    10:-1.28,12:-1.18,15:-1.04,16:-1.0,20:-0.84,25:-0.67,30:-0.52,35:-0.39,40:-0.25,
    45:-0.13,50:0,55:0.13,60:0.25,65:0.39,70:0.52,75:0.67,80:0.84,85:1.04,90:1.28,
    95:1.64,96:1.75,97:1.88,98:2.05,99:2.33};
  return t[pc]!==undefined?t[pc]:null;
}

function sdmtZLabel(z) {
  return zNormMeta(z, false).label;
}

function sdmtSetVersion(v) {
  var esEscrita = v === 'escrita';
  document.getElementById('sdmt-edad-escrita-wrap').style.display = esEscrita ? '' : 'none';
  document.getElementById('sdmt-escol-escrita-wrap').style.display = esEscrita ? '' : 'none';
  document.getElementById('sdmt-edad-oral-wrap').style.display = esEscrita ? 'none' : '';
  document.getElementById('sdmt-escol-oral-wrap').style.display = esEscrita ? 'none' : '';
  // Highlight tab activo
  document.getElementById('sdmt-tab-escrita').style.borderColor = esEscrita ? 'var(--accent)' : 'var(--border)';
  document.getElementById('sdmt-tab-oral').style.borderColor = esEscrita ? 'var(--border)' : 'var(--accent)';
}

function iniciarSDMT() {
  document.getElementById('sdmt-fecha').value = new Date().toISOString().split('T')[0];
  document.getElementById('sdmt-form').style.display = 'block';
  document.getElementById('sdmt-resultado').style.display = 'none';
  // Versión escrita por defecto
  var radios = document.querySelectorAll('[name="sdmt-version"]');
  if (radios.length && !Array.from(radios).some(function(r){return r.checked;})) {
    radios[0].checked = true;
    sdmtSetVersion('escrita');
  }
}

function limpiarSDMT() {
  document.getElementById('sdmt-puntaje').value = '';
  document.getElementById('sdmt-edad-escrita').value = '';
  document.getElementById('sdmt-escol-escrita').value = '';
  document.getElementById('sdmt-edad-oral').value = '';
  document.getElementById('sdmt-escol-oral').value = '';
}

function calcularSDMT() {
  var version = document.querySelector('[name="sdmt-version"]:checked');
  if (!version) { toast('Seleccioná la versión (escrita u oral).','error'); return; }
  version = version.value;

  var puntaje = parseFloat(document.getElementById('sdmt-puntaje').value);
  if (isNaN(puntaje)) { toast('Ingresá el puntaje bruto.','error'); return; }

  var pc, z, m, ds, gi, ei;
  var edadLabel, escolLabel, baremoRef;

  if (version === 'escrita') {
    gi = document.getElementById('sdmt-edad-escrita').value;
    ei = document.getElementById('sdmt-escol-escrita').value;
    if (gi === '' || ei === '') { toast('Seleccioná grupo de edad y escolaridad.','error'); return; }
    gi = parseInt(gi); ei = parseInt(ei);
    pc = sdmtBuscarPc(SDMT_ESCRITA, ei, gi, puntaje);
    z  = sdmtPcToZ(pc);
    var edadLabels = ['18–22','23–27','28–32','33–37','38–42','43–47','48–52','53–57','58–62','63–67','68–72','73–77','>77'];
    edadLabel  = edadLabels[gi]+' años';
    escolLabel = ei===0?'>12 años educación':'1–12 años educación';
    baremoRef  = 'NEURONORMA Argentina — Arango-Lasprilla et al. (2015) NeuroRehabilitation 37(4):625-638';
  } else {
    gi = document.getElementById('sdmt-edad-oral').value;
    ei = document.getElementById('sdmt-escol-oral').value;
    if (gi === '' || ei === '') { toast('Seleccioná grupo de edad y escolaridad.','error'); return; }
    gi = parseInt(gi); ei = parseInt(ei);
    m  = SDMT_ORAL.M[gi][ei];
    ds = SDMT_ORAL.DS[gi][ei];
    z  = parseFloat(((puntaje - m) / ds).toFixed(2));
    // Pc desde Z (tabla normal inversa)
    var zToPc = [[-2.33,1],[-2.05,2],[-1.88,3],[-1.75,4],[-1.64,5],[-1.28,10],[-1.04,15],[-0.84,20],[-0.67,25],[-0.52,30],[-0.25,40],[0,50],[0.25,60],[0.52,70],[0.67,75],[0.84,80],[1.04,85],[1.28,90],[1.64,95],[2.05,98],[2.33,99]];
    pc = 1;
    for (var i=0;i<zToPc.length;i++){ if(z>=zToPc[i][0]) pc=zToPc[i][1]; else break; }
    var edadLabelsO = ['19–35 años','36–50 años','51–70 años'];
    var escolLabelsO = ['3–11 años','12–16 años','>16 años'];
    edadLabel  = edadLabelsO[gi];
    escolLabel = escolLabelsO[ei];
    baremoRef  = 'Vanotti et al. (2015) Applied Neuropsychology: Adult, 22:46-53. Buenos Aires, n=297';
  }

  var lbl = sdmtZLabel(z);
  var detalleHtml =
    '<div class="detalle-item"><div class="detalle-num">'+puntaje+'</div><div class="detalle-lbl">Respuestas<br>correctas</div></div>'+
    '<div class="detalle-item"><div class="detalle-num">Pc '+pc+'</div><div class="detalle-lbl">Percentil</div></div>'+
    '<div class="detalle-item"><div class="detalle-num">'+(z>=0?'+':'')+z+'</div><div class="detalle-lbl">Z</div></div>';

  var interp =
    '<p><strong>Versión:</strong> '+(version==='escrita'?'Escrita':'Oral')+' · Grupo: '+edadLabel+' · Escolaridad: '+escolLabel+'</p>'+
    (version==='oral'&&m!==undefined?'<p><strong>Grupo de referencia:</strong> M='+m+', DS='+ds+'</p>':'')+
    '<p><strong>Resultado:</strong> '+puntaje+' respuestas correctas · Pc '+pc+' · Z='+(z>=0?'+':'')+z+' — '+lbl+'</p>'+
    '<p style="font-size:0.8rem;color:var(--muted);">'+baremoRef+'</p>';

  window._sdmtData = { version:version, puntaje:puntaje, pc:pc, z:z, gi:gi, ei:ei, m:m||null, ds:ds||null };

  document.getElementById('sdmt-detalle').innerHTML = detalleHtml;
  document.getElementById('sdmt-interp').innerHTML  = interp;
  document.getElementById('sdmt-form').style.display = 'none';
  document.getElementById('sdmt-resultado').style.display = 'block';
}

function guardarSDMT() {
  if (!SESSION) return;
  var pacId = document.getElementById('sdmt-paciente').value;
  var fecha = document.getElementById('sdmt-fecha').value;
  if (!pacId) { toast('Seleccioná un paciente.','error'); return; }
  if (!window._sdmtData) { toast('Calculá el resultado antes de guardar.','error'); return; }
  var d = window._sdmtData;
  supaFetch('/rest/v1/psico_resultados','POST',{
    user_id: SESSION.user.id, paciente_id: pacId,
    test: 'SDMT-'+d.version, fecha: fecha,
    puntaje_total: d.puntaje,
    puntaje_z: d.z,
    categoria: sdmtZLabel(d.z),
    datos: { version:d.version, puntaje:d.puntaje, pc:d.pc, z:d.z, gi:d.gi, ei:d.ei, m:d.m, ds:d.ds }
  }, SESSION.access_token).then(function(){
    cargarResultados(); toast('✓ Resultado guardado','success');
    var btnAll = document.querySelectorAll('.vista.active .btn-primary');
    var btn = btnAll.length ? btnAll[btnAll.length-1] : null;
    if (btn) { btn.classList.add('btn-saved'); setTimeout(function(){ btn.classList.remove('btn-saved'); }, 1500); }
  }).catch(catchGuardarError);
}

// ══════════════════════════════════════════════════════════════════════
// GENERAR INFORME WORD (docx nativo, sin dependencias externas)
// Grilla Z estilo González Palau: columnas -3…+3 con zona sombreada
// ══════════════════════════════════════════════════════════════════════

// ── CRC32 (requerido por el formato ZIP) ──────────────────────────────
var _CRC32_TABLE = (function(){
  var t = new Uint32Array(256);
  for(var i=0;i<256;i++){var c=i;for(var j=0;j<8;j++)c=c&1?(0xEDB88320^(c>>>1)):c>>>1;t[i]=c;}
  return t;
})();
function _crc32(buf) {
  var c=0xFFFFFFFF;
  for(var i=0;i<buf.length;i++) c=_CRC32_TABLE[(c^buf[i])&0xFF]^(c>>>8);
  return (c^0xFFFFFFFF)>>>0;
}

// ── Generador de ZIP (método stored, sin compresión) ──────────────────
function _makeZip(files) {
  // files: [{name, data: Uint8Array}]
  var enc = new TextEncoder();
  var localHeaders = [], centralDir = [], offset = 0;
  files.forEach(function(f) {
    var nameBuf = enc.encode(f.name);
    var data    = f.data instanceof Uint8Array ? f.data : enc.encode(f.data);
    var crc     = _crc32(data);
    var size    = data.length;
    // Local header
    var lh = new Uint8Array(30 + nameBuf.length);
    var v = new DataView(lh.buffer);
    v.setUint32(0, 0x04034b50, true); // sig
    v.setUint16(4, 20, true);          // version needed
    v.setUint16(6, 0, true);           // flags
    v.setUint16(8, 0, true);           // method: stored
    v.setUint16(10, 0, true); v.setUint16(12, 0, true); // time/date
    v.setUint32(14, crc,  true);
    v.setUint32(18, size, true);
    v.setUint32(22, size, true);
    v.setUint16(26, nameBuf.length, true);
    v.setUint16(28, 0, true);
    lh.set(nameBuf, 30);
    localHeaders.push({ lh: lh, data: data, nameBuf: nameBuf, crc: crc, size: size, offset: offset });
    offset += lh.length + data.length;
    // Central dir entry
    var cd = new Uint8Array(46 + nameBuf.length);
    var cv = new DataView(cd.buffer);
    cv.setUint32(0, 0x02014b50, true);
    cv.setUint16(4, 20, true); cv.setUint16(6, 20, true);
    cv.setUint16(8, 0, true);  cv.setUint16(10, 0, true);
    cv.setUint16(12, 0, true); cv.setUint16(14, 0, true);
    cv.setUint32(16, crc,  true);
    cv.setUint32(20, size, true);
    cv.setUint32(24, size, true);
    cv.setUint16(28, nameBuf.length, true);
    cv.setUint16(30, 0, true); cv.setUint16(32, 0, true);
    cv.setUint16(34, 0, true); cv.setUint16(36, 0, true);
    cv.setUint32(40, 0, true);
    cv.setUint32(42, localHeaders[localHeaders.length-1].offset, true);
    cd.set(nameBuf, 46);
    centralDir.push(cd);
  });
  var cdSize   = centralDir.reduce(function(a,b){return a+b.length;},0);
  var cdOffset = offset;
  // End of central dir
  var eocd = new Uint8Array(22);
  var ev = new DataView(eocd.buffer);
  ev.setUint32(0, 0x06054b50, true);
  ev.setUint16(4, 0, true); ev.setUint16(6, 0, true);
  ev.setUint16(8, files.length, true);
  ev.setUint16(10, files.length, true);
  ev.setUint32(12, cdSize,   true);
  ev.setUint32(16, cdOffset, true);
  ev.setUint16(20, 0, true);
  // Concat all
  var chunks = [];
  localHeaders.forEach(function(e){ chunks.push(e.lh, e.data); });
  centralDir.forEach(function(c){ chunks.push(c); });
  chunks.push(eocd);
  var total = chunks.reduce(function(a,b){return a+b.length;},0);
  var out = new Uint8Array(total), pos=0;
  chunks.forEach(function(c){ out.set(c, pos); pos += c.length; });
  return out;
}

// ── Escape XML ────────────────────────────────────────────────────────
function _xe(s) {
  if (s === null || s === undefined) return '';
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

// ── Colores ───────────────────────────────────────────────────────────
var WC = { VERDE_OSC:'2a6e6e', VERDE_MED:'3a8f8f', VERDE_CLR:'B8DDB0', GRIS_CLR:'EEEEEE', BLANCO:'FFFFFF' };

// ── Helpers XML docx ──────────────────────────────────────────────────
function _wRun(txt, opts) {
  opts = opts || {};
  var rpr = '<w:rPr>';
  if (opts.bold)    rpr += '<w:b/>';
  if (opts.ital)    rpr += '<w:i/>';
  if (opts.color)   rpr += '<w:color w:val="'+opts.color+'"/>';
  if (opts.sz)      rpr += '<w:sz w:val="'+_wordSz(opts.sz)+'"/><w:szCs w:val="'+_wordSz(opts.sz)+'"/>';
  if (opts.font)    rpr += '<w:rFonts w:ascii="'+opts.font+'" w:hAnsi="'+opts.font+'" w:cs="'+opts.font+'"/>';
  rpr += '</w:rPr>';
  return '<w:r>'+rpr+'<w:t xml:space="preserve">'+_xe(txt)+'</w:t></w:r>';
}

function _wPar(runs, opts) {
  opts = opts || {};
  var ppr = '<w:pPr>';
  if (opts.align)    ppr += '<w:jc w:val="'+opts.align+'"/>';
  if (opts.before||opts.after) {
    ppr += '<w:spacing w:before="'+(opts.before||0)+'" w:after="'+(opts.after||80)+'"/>';
  }
  if (opts.shading)  ppr += '<w:shd w:val="clear" w:color="auto" w:fill="'+opts.shading+'"/>';
  if (opts.border_b) ppr += '<w:pBdr><w:bottom w:val="single" w:sz="6" w:space="1" w:color="'+opts.border_b+'"/></w:pBdr>';
  ppr += '</w:pPr>';
  if (!Array.isArray(runs)) runs = [runs];
  return '<w:p>'+ppr+runs.join('')+'</w:p>';
}

function _wCell(content, opts) {
  opts = opts || {};
  var tcp = '<w:tcPr>';
  if (opts.w)    tcp += '<w:tcW w:w="'+opts.w+'" w:type="dxa"/>';
  if (opts.fill) tcp += '<w:shd w:val="clear" w:color="auto" w:fill="'+opts.fill+'"/>';
  if (opts.span) tcp += '<w:gridSpan w:val="'+opts.span+'"/>';
  var bColor = opts.hdrBorder ? '595959' : 'BFBFBF';
  var bSz    = opts.hdrBorder ? '10' : '6';
  tcp += '<w:tcBorders>';
  tcp += '<w:top    w:val="single" w:sz="'+bSz+'" w:color="'+bColor+'"/>';
  tcp += '<w:bottom w:val="single" w:sz="'+bSz+'" w:color="'+bColor+'"/>';
  tcp += '<w:left   w:val="single" w:sz="'+bSz+'" w:color="'+bColor+'"/>';
  tcp += '<w:right  w:val="single" w:sz="'+bSz+'" w:color="'+bColor+'"/>';
  tcp += '</w:tcBorders>';
  if (opts.noWrap) tcp += '<w:noWrap/>';
  var mLR = opts.compact ? 0 : 30;
  tcp += '<w:tcMar><w:top w:w="0" w:type="dxa"/><w:bottom w:w="0" w:type="dxa"/><w:left w:w="'+mLR+'" w:type="dxa"/><w:right w:w="'+mLR+'" w:type="dxa"/></w:tcMar>';
  tcp += '</w:tcPr>';
  return '<w:tc>'+tcp+content+'</w:tc>';
}

function _wRow(cells, opts) {
  opts = opts || {};
  var trpr = opts.hdr 
    ? '<w:trPr><w:tblHeader/><w:cantSplit/></w:trPr>' 
    : '<w:trPr><w:cantSplit/></w:trPr>';
  return '<w:tr>'+trpr+cells.join('')+'</w:tr>';
}

function _wTable(rows, colWidths) {
  var totalW = colWidths.reduce(function(a,b){return a+b;},0);
  var tblGrid = '<w:tblGrid>'+colWidths.map(function(w){return '<w:gridCol w:w="'+w+'"/>';}).join('')+'</w:tblGrid>';
  var tblPr = '<w:tblPr>'+
    '<w:tblW w:w="'+totalW+'" w:type="dxa"/>'+
    '<w:tblLayout w:type="fixed"/>'+
    '<w:tblBorders>'+
      '<w:top    w:val="single" w:sz="12" w:color="595959"/>'+
      '<w:bottom w:val="single" w:sz="12" w:color="595959"/>'+
      '<w:left   w:val="single" w:sz="12" w:color="595959"/>'+
      '<w:right  w:val="single" w:sz="12" w:color="595959"/>'+
      '<w:insideH w:val="single" w:sz="6" w:color="BFBFBF"/>'+
      '<w:insideV w:val="single" w:sz="6" w:color="BFBFBF"/>'+
    '</w:tblBorders>'+
  '</w:tblPr>';
  return '<w:tbl>'+tblPr+tblGrid+rows.join('')+'</w:tbl>';
}

function _wSubescalaTable(rows, colWidths) {
  var totalW = colWidths.reduce(function(a,b){return a+b;},0);
  var tblGrid = '<w:tblGrid>'+colWidths.map(function(w){return '<w:gridCol w:w="'+w+'"/>';}).join('')+'</w:tblGrid>';
  var tblPr = '<w:tblPr>'+
    '<w:tblW w:w="'+totalW+'" w:type="dxa"/>'+
    '<w:tblLayout w:type="fixed"/>'+
    '<w:tblBorders>'+
      '<w:top    w:val="single" w:sz="6" w:color="BFBFBF"/>'+
      '<w:bottom w:val="single" w:sz="6" w:color="BFBFBF"/>'+
      '<w:left   w:val="single" w:sz="6" w:color="BFBFBF"/>'+
      '<w:right  w:val="single" w:sz="6" w:color="BFBFBF"/>'+
      '<w:insideH w:val="single" w:sz="6" w:color="BFBFBF"/>'+
      '<w:insideV w:val="single" w:sz="6" w:color="BFBFBF"/>'+
    '</w:tblBorders>'+
  '</w:tblPr>';
  return '<w:tbl>'+tblPr+tblGrid+rows.join('')+'</w:tbl>';
}

