function famAvdItemSignificativo(v) {
  if (v == null || v === '') return false;
  var n = parseInt(v, 10);
  return !isNaN(n) && n >= 2;
}

function famAvdHaySignificativo(obj, items) {
  if (!obj || typeof obj !== 'object') return null;
  var hayDato = false, alguno = false;
  items.forEach(function(it) {
    var v = obj[it.id];
    if (v != null && v !== '') {
      hayDato = true;
      if (famAvdItemSignificativo(v)) alguno = true;
    }
  });
  return hayDato ? alguno : null;
}

function famReporteSintomasAvd(obj, items) {
  if (!obj || typeof obj !== 'object') return '—';
  var partes = [];
  items.forEach(function(it) {
    var v = obj[it.id];
    if (!famAvdItemSignificativo(v)) return;
    var opt = (it.options || []).filter(function(o){ return String(o.v) === String(parseInt(v, 10)); })[0];
    partes.push(opt ? opt.t.replace(/^\d+\s*·\s*/, '') : it.label);
  });
  return partes.length ? partes.join(' ; ') : '—';
}

function famReporteSintomasAd8(ad8Obj) {
  if (!ad8Obj || typeof ad8Obj !== 'object') return '—';
  var partes = [];
  FAM_AD8.forEach(function(it) {
    if (ad8Obj[it.id] === 'si') partes.push(it.label);
  });
  return partes.length ? partes.join(' ; ') : '—';
}

function iniciarFamiliar() {
  document.getElementById('familiar-fecha').value = new Date().toISOString().split('T')[0];
  document.getElementById('familiar-form').style.display = 'block';
  _renderFamiliarGrids();
}

function _renderFamiliarGrids() {
  // NPI-Q
  var npiqG = document.getElementById('npiq-grid');
  npiqG.innerHTML = '';
  FAM_NPIQ.forEach(function(item) {
    var d = document.createElement('div');
    d.style.cssText = 'background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:10px 12px;';
    d.innerHTML = '<div style="font-size:0.82rem;font-weight:600;color:var(--text);margin-bottom:4px;">'+item.label+'</div>'+
      (item.prompt ? '<div style="font-size:0.75rem;color:var(--muted);margin-bottom:8px;line-height:1.35;">'+item.prompt+'</div>' : '')+
      '<div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">'+
      '<label style="display:flex;align-items:center;gap:4px;font-size:0.78rem;cursor:pointer;">'+
        '<input type="checkbox" id="npiq-'+item.id+'-pres" onchange="npiqChk(\''+item.id+'\')"> Sí'+
      '</label>'+
      '<select id="npiq-'+item.id+'-grav" disabled style="font-size:0.78rem;padding:2px 6px;border:1px solid var(--border);border-radius:4px;background:var(--bg);">'+
        '<option value="0">— gravedad —</option>'+
        '<option value="1">1 · Leve</option>'+
        '<option value="2">2 · Moderado</option>'+
        '<option value="3">3 · Severo</option>'+
      '</select>'+
      '<span style="font-size:0.75rem;color:var(--muted);">No = ausente</span>'+
      '</div>';
    npiqG.appendChild(d);
  });

  // AD8
  var ad8G = document.getElementById('ad8-grid');
  ad8G.innerHTML = '';
  FAM_AD8.forEach(function(item) {
    var d = document.createElement('div');
    d.style.cssText = 'background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:10px 12px;';
    d.innerHTML = '<div style="font-size:0.82rem;font-weight:600;color:var(--text);margin-bottom:8px;line-height:1.35;">'+item.n+'. '+item.label+'</div>'+
      '<div style="display:flex;gap:10px;flex-wrap:wrap;">'+
      ['si','no','nose'].map(function(v,i){
        var lbl = ['Sí','No','No sabe'][i];
        return '<label style="display:flex;align-items:center;gap:4px;font-size:0.78rem;cursor:pointer;">'+
          '<input type="radio" name="ad8-'+item.id+'" value="'+v+'" onchange="ad8Calc()"> '+lbl+'</label>';
      }).join('')+
      '</div>';
    ad8G.appendChild(d);
  });

  // AVD grids (escala 0–3 según protocolo)
  function renderAvd(items, containerId) {
    var g = document.getElementById(containerId);
    g.innerHTML = '';
    items.forEach(function(item) {
      var opts = (item.options || []).map(function(o) {
        return '<option value="'+o.v+'">'+o.t+'</option>';
      }).join('');
      var d = document.createElement('div');
      d.style.cssText = 'background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:10px 12px;';
      d.innerHTML = '<div style="font-size:0.82rem;font-weight:600;color:var(--text);margin-bottom:8px;">'+item.label+'</div>'+
        '<select name="'+containerId+'-'+item.id+'" style="width:100%;font-size:0.78rem;padding:5px 8px;border:1px solid var(--border);border-radius:4px;background:var(--bg);color:var(--text);">'+
        '<option value="">— Seleccionar nivel —</option>'+opts+
        '</select>';
      g.appendChild(d);
    });
  }
  renderAvd(FAM_AVDB, 'avdb-grid');
  renderAvd(FAM_AVDI, 'avdi-grid');
  renderAvd(FAM_AVDE, 'avde-grid');
}

function npiqChk(id) {
  var pres = document.getElementById('npiq-'+id+'-pres');
  var grav = document.getElementById('npiq-'+id+'-grav');
  grav.disabled = !pres.checked;
  if (!pres.checked) grav.value = '0';
}

function ad8Calc() {
  var total = FAM_AD8.filter(function(item){
    var sel = document.querySelector('input[name="ad8-'+item.id+'"]:checked');
    return sel && sel.value === 'si';
  }).length;
  var box = document.getElementById('ad8-total-box');
  box.style.display = 'block';
  var sig = total >= 2;
  box.style.background = sig ? '#fad8d8' : '#d4f0e2';
  box.style.color = sig ? '#a00000' : '#1a6e3a';
  box.style.border = '1px solid ' + (sig ? '#e6b0b0' : '#9fd4b8');
  box.textContent = 'Total AD8-ARG: ' + total + '/8 — ' + (sig ? 'Significativo (≥ 2 · posible deterioro cognitivo)' : 'Sin significancia clínica (< 2)');
}

function limpiarFamiliar() {
  document.getElementById('familiar-informante').value = '';
  _renderFamiliarGrids();
  document.getElementById('ad8-total-box').style.display = 'none';
}

function _getFamData() {
  // NPI-Q
  var npiq = {};
  FAM_NPIQ.forEach(function(item){
    var pres = document.getElementById('npiq-'+item.id+'-pres');
    var grav = document.getElementById('npiq-'+item.id+'-grav');
    npiq[item.id] = (pres && pres.checked) ? parseInt(grav.value)||1 : 0;
  });
  var npiqTotal = Object.values(npiq).reduce(function(a,b){return a+(b>0?1:0);},0);
  var hayNpiq = npiqTotal > 0;

  // AD8
  var ad8 = {};
  var ad8Total = 0;
  FAM_AD8.forEach(function(item){
    var sel = document.querySelector('input[name="ad8-'+item.id+'"]:checked');
    ad8[item.id] = sel ? sel.value : null;
    if (sel && sel.value === 'si') ad8Total++;
  });
  var hayAD8 = FAM_AD8.some(function(item){ return ad8[item.id] !== null; });

  // AVD helper
  function getAvd(items, prefix) {
    var avd = {}, total = 0, hay = false;
    items.forEach(function(item){
      var el = document.querySelector('select[name="'+prefix+'-'+item.id+'"]');
      avd[item.id] = el && el.value !== '' ? parseInt(el.value, 10) : null;
      if (el && el.value !== '') { hay = true; total += parseInt(el.value, 10); }
    });
    return {data: avd, total: total, hay: hay};
  }
  var avdb = getAvd(FAM_AVDB, 'avdb-grid');
  var avdi = getAvd(FAM_AVDI, 'avdi-grid');
  var avde = getAvd(FAM_AVDE, 'avde-grid');

  return {
    informante: document.getElementById('familiar-informante').value || null,
    npiq: hayNpiq ? npiq : null,
    npiqTotal: npiqTotal,
    ad8: hayAD8 ? ad8 : null,
    ad8Total: ad8Total,
    avdb: avdb.hay ? avdb.data : null,
    avdbTotal: avdb.total,
    avdi: avdi.hay ? avdi.data : null,
    avdiTotal: avdi.total,
    avde: avde.hay ? avde.data : null,
    avdeTotal: avde.total
  };
}

function guardarFamiliar() {
  if (!SESSION) return;
  var pacId = document.getElementById('familiar-paciente').value;
  var fecha = document.getElementById('familiar-fecha').value;
  if (!pacId) { toast('Seleccioná un paciente.','error'); return; }
  var d = _getFamData();
  if (!d.npiq && !d.ad8 && !d.avdb && !d.avdi && !d.avde) {
    toast('Completá al menos un cuestionario antes de guardar.','error'); return;
  }
  var resumen = [];
  if (d.npiq)  resumen.push('NPI-Q: '+ d.npiqTotal +' síntomas');
  if (d.ad8)   resumen.push('AD8: '+ d.ad8Total +'/8');
  if (d.avdb)  resumen.push('AVD Básicas: '+ d.avdbTotal);
  if (d.avdi)  resumen.push('AVD Instr.: '+ d.avdiTotal);
  if (d.avde)  resumen.push('AVD Expan.: '+ d.avdeTotal);

  supaFetch('/rest/v1/psico_resultados','POST',{
    user_id: SESSION.user.id, paciente_id: pacId,
    test: 'Cuestionarios Familiares', fecha: fecha,
    puntaje_total: d.ad8Total,
    puntaje_z: null,
    categoria: resumen.join(' · '),
    datos: d
  }, SESSION.access_token).then(function(){
    cargarResultados();
    toast('✓ Cuestionarios familiares guardados','success');
    var btnAll = document.querySelectorAll('.vista.active .btn-primary');
    var btn = btnAll.length ? btnAll[btnAll.length-1] : null;
    if (btn) { btn.classList.add('btn-saved'); setTimeout(function(){ btn.classList.remove('btn-saved'); },1500); }
  }).catch(catchGuardarError);
}

window.addEventListener('DOMContentLoaded', function() {
  initGlosarioDelegacion();
  actualizarSaludo();
  cargarLogosUI();
  initFirmasUI();
  preloadFirmasIntegradas();
  // Siempre arrancar en el login — nunca restaurar sesión automáticamente
  try { localStorage.removeItem('psico_session'); } catch(e) {}
  var login = document.getElementById('screen-login');
  login.style.display = 'flex';
  login.classList.add('active');
});

